va="/projects/Tonybot/en/latest/assets/image3.c5846TvI.png",Ta="/projects/Tonybot/en/latest/assets/image3.Bpkg0XbT.png",Ca="/projects/Tonybot/en/latest/assets/image4.DBTqAskn.png",Ea="/projects/Tonybot/en/latest/assets/image6.o5vJyk1D.png",za="/projects/Tonybot/en/latest/assets/image5.DwJKqRrE.png",Ua="/projects/Tonybot/en/latest/assets/image8.B14fjtvC.png",Ra="/projects/Tonybot/en/latest/assets/image9.CNcMB6gD.png",qa="/projects/Tonybot/en/latest/assets/image2.qm0CTki8.png",Sa="/projects/Tonybot/en/latest/assets/image3.Bpkg0XbT.png",Oa="/projects/Tonybot/en/latest/assets/image4.DBTqAskn.png",Ia="/projects/Tonybot/en/latest/assets/image5.DwJKqRrE.png",Ba="/projects/Tonybot/en/latest/assets/image6.D5Vc_KLN.png",Da=JSON.parse('{"title":"5. Scratch Programming Projects","description":"","frontmatter":{},"headers":[],"relativePath":"docs/5.scratch_programming_projects.md","filePath":"docs/5.scratch_programming_projects.md"}'),Pa={name:"docs/5.scratch_programming_projects.md"};function xa(Za,t,Ya,Ma,Va,ja){return ft(),yt("div",null,[...t[0]||(t[0]=[vt('<h1 id="_5-scratch-programming-projects" tabindex="-1">5. Scratch Programming Projects <a class="header-anchor" href="#_5-scratch-programming-projects" aria-label="Permalink to &quot;5. Scratch Programming Projects&quot;">​</a></h1><h2 id="_5-1-wondercode-user-guide" tabindex="-1">5.1 WonderCode User Guide <a class="header-anchor" href="#_5-1-wondercode-user-guide" aria-label="Permalink to &quot;5.1 WonderCode User Guide&quot;">​</a></h2><h3 id="_5-1-1-wondercode-software-overview-and-installation" tabindex="-1">5.1.1 WonderCode Software Overview and Installation <a class="header-anchor" href="#_5-1-1-wondercode-software-overview-and-installation" aria-label="Permalink to &quot;5.1.1 WonderCode Software Overview and Installation&quot;">​</a></h3><p>WonderCode is a Scratch-based programming tool designed specifically for Hiwonder products. It supports the automatic conversion between graphical command blocks and Python code. By simply dragging and dropping command blocks, users can easily write programs, making it a great choice for beginners learning to program.</p><img loading="lazy" height="893" width="1386" class="common_img" src="'+Tt+'"><p>(1) Locate and open the installation file &quot;<a href="https://drive.google.com/drive/folders/1DvebM-ic0hn_MFobA7cVo24GZoXOLTgP?usp=sharing" target="_blank" rel="noreferrer"><strong>WonderCode setup.exe</strong></a>&quot; in the same folder as this document, or find it in the &quot;<strong>Appendix</strong>&quot;.</p><img loading="lazy" height="100" width="83" class="common_img" src="'+Ct+'"><p>(2) In the &quot;<strong>Select Installation Language</strong>&quot; window, choose &quot;<strong>English</strong>,&quot; then click &quot;<strong>OK</strong>.&quot;</p><img loading="lazy" height="162" width="349" class="common_img" src="'+Et+'"><p>(3) Select your preferred installation location. You can either use the default folder or choose a custom path. Once done, click <strong>&quot;Next.&quot;</strong></p><img loading="lazy" height="415" width="582" class="common_img" src="'+zt+'"><p>(4) The <strong>&quot;Additional Tasks&quot;</strong> window will appear. The option to <strong>&quot;Create Desktop Shortcut&quot;</strong> is selected by default. You can leave this as is and click <strong>&quot;Next&quot;</strong> to continue.</p><img loading="lazy" height="415" width="582" class="common_img" src="'+Ut+'"><p>(5) Click the <strong>&quot;Install&quot;</strong> button to begin the installation process.</p><img loading="lazy" height="415" width="582" class="common_img" src="'+Rt+'"><p>(6) The installation will begin, and a progress bar will be displayed to show the status.</p><img loading="lazy" height="415" width="582" class="common_img" src="'+e+'"><p>(7) Once the installation is finished, click <strong>&quot;Finish&quot;</strong> to complete the process.</p><img loading="lazy" height="415" width="582" class="common_img" src="'+e+'"><p>(8) After installation, the <strong>&quot;WonderCode&quot;</strong> icon will appear on your desktop.</p><img loading="lazy" height="77" width="79" class="common_img" src="'+o+'"><h3 id="_5-1-2-device-connection" tabindex="-1">5.1.2 Device Connection <a class="header-anchor" href="#_5-1-2-device-connection" aria-label="Permalink to &quot;5.1.2 Device Connection&quot;">​</a></h3><p>(1) Connect your device and double-click to launch the &quot;<a href="https://drive.google.com/drive/folders/1DvebM-ic0hn_MFobA7cVo24GZoXOLTgP?usp=sharing" target="_blank" rel="noreferrer"><strong>WonderCode</strong></a>&quot; software.</p><img loading="lazy" height="77" width="79" class="common_img" src="'+o+'"><p>(2) Before you can connect, you&#39;ll need to add the device&#39;s extension package. Without it, the connection won&#39;t work. To add the extension, click the &quot;<strong>Add Extension</strong>&quot; button <img loading="lazy" height="49" width="59" src="'+qt+'" style="width:70px;"> located in the bottom-left corner of the main interface. In the pop-up window, select <strong>&quot;Robot -&gt; Tonybot&quot;</strong> in order.</p><img loading="lazy" height="432" width="1382" class="common_img" src="'+St+'"><p>(3) After that, click the &quot;<strong>Connect</strong>&quot; button and choose the correct port for the connection.</p><img loading="lazy" height="214" width="780" class="common_img" src="'+Ot+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port number can vary based on your system&#39;s setup. For instance, in this case, the port number used is &quot;<strong>COM4</strong>&quot;, but avoid using &quot;<strong>COM1</strong>&quot;, as it&#39;s typically the system&#39;s communication port.</p></section><p>If you&#39;re connecting multiple USB devices and aren&#39;t sure which port to use, you can find it by opening <strong>&quot;This PC&quot;</strong> on your desktop. Then go to <strong>&quot;Properties -&gt; Device Manager,&quot;</strong> where you&#39;ll find the port corresponding to the Tonybot controller (it will show as &quot;<strong>CH340</strong>&quot;).</p><img loading="lazy" height="625" width="904" class="common_img" src="'+It+'"><p>(4) Once the device and software are successfully paired, you should see a confirmation message indicating the connection was successful.</p><img loading="lazy" height="57" width="176" class="common_img" src="'+Bt+'"><h3 id="_5-1-3-function-description" tabindex="-1">5.1.3 Function Description <a class="header-anchor" href="#_5-1-3-function-description" aria-label="Permalink to &quot;5.1.3 Function Description&quot;">​</a></h3><p>The image below illustrates the functional areas of the &quot;<strong>WonderCode</strong>&quot; software:</p><p>① Menu Bar,</p><p>② Command Area,</p><p>③ Script Area,</p><p>④ Code Display and Upload Area.</p><img loading="lazy" height="893" width="1386" class="common_img" src="'+Pt+'"><p>The functions corresponding to each area are listed in the table below:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="49" width="99" src="'+xt+'"></td><td style="text-align:center;"><strong>Create, Save, and Open Program Files</strong>: This option allows you to create, save, and open program files.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="48" width="101" src="'+Zt+'"></td><td style="text-align:center;"><strong>Online Mode (Reference Only)</strong>: This section is for understanding the online mode. No need to master it for now.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="44" width="185" src="'+Yt+'"></td><td style="text-align:center;"><strong>Connect Device and Software</strong>: Use this to connect your device to the software and choose the appropriate port.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="45" width="104" src="'+Mt+'"></td><td style="text-align:center;"><strong>Help, Updates, and Driver Installation</strong>: Access help, check for updates, or install necessary drivers here.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="52" width="194" src="'+Vt+'"></td><td style="text-align:center;"><strong>Program File Name Display</strong>: Displays the name of the program file. If you haven&#39;t started programming or the file isn&#39;t saved yet, it will show &quot;<strong>Scratch Project</strong>&quot;.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="51" width="253" src="'+jt+'"></td><td style="text-align:center;"><strong>Switch Between Modes</strong>: Use this button to toggle between &quot;Online Mode&quot; and &quot;Upload Mode.&quot; Be sure to save your work before switching, as unsaved files will be lost (Note: Online Mode is used for activities like playing animations and making games, while Upload Mode is for interacting with your device and utilizing its features).</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="42" width="56" src="'+kt+'"></td><td style="text-align:center;"><strong>Language Options</strong>: Choose the language for the interface, with options for English, Simplified Chinese, and Traditional Chinese.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="46" width="87" src="'+Qt+'"></td><td style="text-align:center;"><strong>Undo and Redo</strong>: Easily undo or redo actions during programming.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="53" width="278" src="'+Lt+'"></td><td style="text-align:center;"><strong>Switch Editing Modes</strong>: Toggle between &quot;<strong>Auto Transcoding</strong>&quot;, which converts block-based programming into Python, and &quot;<strong>Python Programming</strong>&quot;, where you can directly edit with Python.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="45" width="49" src="'+Dt+'"></td><td style="text-align:center;"><strong>Save as Python Code</strong>: Save your program in Python code format.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="47" width="52" src="'+Nt+'"></td><td style="text-align:center;"><strong>Open Saved Python Files</strong>: Open Python files you&#39;ve previously saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="45" width="57" src="'+Xt+'"></td><td style="text-align:center;"><strong>Device Interaction</strong>: Download your program to the main control board for device interaction.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="50" width="61" src="'+Ht+'"></td><td style="text-align:center;"><strong>Add Device Extension Package</strong>: Add necessary extensions for your device here.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="156" width="67" src="'+Wt+'"></td><td style="text-align:center;"><strong>Zoom Controls</strong>: Adjust the zoom for your code editing interface, or reset it to the default size.</td></tr></tbody></table><h3 id="_5-1-4-programming-instructions" tabindex="-1">5.1.4 Programming Instructions <a class="header-anchor" href="#_5-1-4-programming-instructions" aria-label="Permalink to &quot;5.1.4 Programming Instructions&quot;">​</a></h3><p>Here&#39;s an example to guide you through programming to light up the ultrasonic RGB LEDs:</p><p>(1) Find the <strong>&quot;Tonybot Main Program&quot;</strong> block within the Tonybot command set and drag it into the code editing area.</p><img loading="lazy" height="444" width="882" class="common_img" src="'+Kt+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If you want to remove a block, simply drag it back to the command set area from the code editing section.</p></section><p>(2) Next, drag the &quot;<strong>Repeat</strong>&quot; block from the control command set and place it below the previous block.</p><img loading="lazy" height="433" width="884" class="common_img" src="'+Ft+'"><p>(3) In the lower-left corner, add the <strong>&quot;Glowy Ultrasonic Sensor&quot;</strong> extension package.</p><img loading="lazy" height="753" width="888" class="common_img" src="'+Jt+'"><img loading="lazy" height="697" width="1378" class="common_img" src="'+Gt+'"><p>(4) From the sensor command set, drag out the block to set the color of the ultrasonic LED lights. Place it inside the <strong>&quot;Repeat&quot;</strong> block and configure all LEDs to glow red.</p><img loading="lazy" height="456" width="1343" class="common_img" src="'+_t+'"><img loading="lazy" height="398" width="682" class="common_img" src="'+$t+'"><img loading="lazy" height="201" width="500" class="common_img" src="'+te+'"><p>(5) Once you&#39;re done, click <strong>&quot;Upload&quot;</strong> to transfer the program to the main controller.</p><img loading="lazy" height="175" width="500" class="common_img" src="'+ee+'"><p>(6) To save your work, click &quot;<strong>File -&gt; Save to Computer</strong>&quot; in the top-left corner.</p><img loading="lazy" height="189" width="500" class="common_img" src="'+oe+'"><h2 id="_5-2-secondary-development-course" tabindex="-1">5.2 Secondary Development Course <a class="header-anchor" href="#_5-2-secondary-development-course" aria-label="Permalink to &quot;5.2 Secondary Development Course&quot;">​</a></h2><h3 id="_5-2-1-breathing-light-project" tabindex="-1">5.2.1 Breathing Light Project <a class="header-anchor" href="#_5-2-1-breathing-light-project" aria-label="Permalink to &quot;5.2.1 Breathing Light Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>In this lesson, we will make the RGB LED on the ultrasonic sensor blink.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+se+'"><ul><li><strong>Introduction to Glowy Ultrasonic Sensor</strong></li></ul><img loading="lazy" height="323" width="497" class="common_img" src="'+ne+'" style="width:300px;"><p>This is a glowy ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><p>The ultrasonic sensor is pre-installed on the robot when it leaves the factory.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Breathing%20Light%20Program.zip">Breathing Light Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+ie+'" style="width:70px;">.</p><p>(2) Drag the <strong>&quot;02 Breathing Light Program.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="351" width="1383" class="common_img" src="'+ae+'"><p>(3) In the menu bar, click on <strong>&quot;Connect device&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a <strong>&quot;Connect Success&quot;</strong> message.</p><img loading="lazy" height="259" width="763" class="common_img" src="'+re+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+le+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+ce+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+ge+'"><ul><li>Achieved Effect</li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>For optimal experience, it is recommended to use this feature in a dimly lit environment.</p></section><p>The RGB lights on the ultrasonic device will emit blue light and flash every 2 seconds.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+n+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Breathing%20Light%20Program.zip">Breathing Light Program</a></p><p>(1) Initialize the posture of Tonybot and configure the flags for the buttons and actions.</p><img loading="lazy" height="233" width="512" class="common_img" src="'+de+'"><p>(2) In the main program, set the color and cycle period for the ultrasonic RGB lights.</p><img loading="lazy" height="166" width="594" class="common_img" src="'+he+'"><ul><li><strong>Function Extension</strong></li></ul><p>To modify the color and cycle duration of the ultrasonic device, simply adjust the color settings and cycle time (in seconds). Additionally, the left and right RGB lights of the device can be set to different colors.</p><img loading="lazy" height="166" width="594" class="common_img" src="'+me+'"><h3 id="_5-2-2-distance-ranging-display-project" tabindex="-1">5.2.2 Distance Ranging &amp; Display Project <a class="header-anchor" href="#_5-2-2-distance-ranging-display-project" aria-label="Permalink to &quot;5.2.2 Distance Ranging &amp; Display Project&quot;">​</a></h3><ul><li><strong>Sensor Installation &amp; Wiring</strong></li></ul><img loading="lazy" height="600" width="1200" class="common_img" src="'+i+'"><img loading="lazy" height="675" width="1200" class="common_img" src="'+a+'"><ul><li><strong>Project Introduction</strong></li></ul><p>This section utilizes the ultrasonic module to measure the distance to an obstacle. The measured distance is displayed on the LED dot matrix, and the RGB light color of the ultrasonic module is adjusted accordingly.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="470" width="1268" class="common_img" src="'+pe+'"><ul><li><strong>Sensor Introduction</strong></li></ul><p>(1) Glowy Ultrasonic Sensor</p><img loading="lazy" height="323" width="497" class="common_img" src="'+Ae+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><p>(2) LED Dot Matrix Display</p><p>The LED dot matrix module utilizes an LED display screen that offers high brightness, flicker-free performance, and easy wiring. It is capable of displaying numbers, text, patterns, and other content. The module consists of two red 8x8 LED matrices and is controlled by the TM640B driver chip, which enables efficient control of the dot matrix screen.</p><img loading="lazy" height="296" width="659" class="common_img" src="'+ue+'" style="width:300px;"><p>For a detailed introduction to the installation and assembly process, please refer to the tutorial video.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Distance%20Ranging%20&amp;%20Display%20Program.zip">Distance Ranging &amp; Display Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+be+'" style="width:70px;"></p><p>(2) Drag the <strong>&quot;03 Distance Ranging &amp; Display.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="349" width="1384" class="common_img" src="'+we+'"><p>(3) In the menu bar, click on <strong>&quot;Connect device&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a <strong>&quot;Connect Success&quot;</strong> message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+fe+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+ye+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+ve+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+Te+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>Slowly bring the object closer to the glowy ultrasonic sensor. As the distance decreases, the ultrasonic light will shift towards red, and as the distance increases, it will become greener. The LED dot matrix display will update in real-time to show the measured distance.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+r+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Distance%20Ranging%20&amp;%20Display%20Program.zip">Distance Ranging &amp; Display Program</a></p><p>(1) Initialize Tonybot&#39;s posture, set up the dot matrix, and configure the initial action sequence.</p><img loading="lazy" height="256" width="617" class="common_img" src="'+Ce+'"><p>(2) In the main program, assign the detected obstacle distance to the variable <strong>&#39;distance,&#39;</strong> display this distance numerically on the dot matrix screen, and introduce a 0.1-second delay.</p><img loading="lazy" height="237" width="680" class="common_img" src="'+Ee+'"><ul><li><strong>FAQ</strong></li></ul><p><strong>Q: Why is the ultrasound distance measurement sometimes accurate and sometimes inaccurate?</strong></p><p><strong>A:</strong> For optimal accuracy, please use smooth, flat surfaces when measuring distance, and avoid prolonged close-range measurements of obstacles.</p><h3 id="_5-2-3-distance-controlled-walking-project" tabindex="-1">5.2.3 Distance-Controlled Walking Project <a class="header-anchor" href="#_5-2-3-distance-controlled-walking-project" aria-label="Permalink to &quot;5.2.3  Distance-Controlled Walking Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>In this lesson, the ultrasonic sensor is used to measure obstacles in front of the robot. When the detected distance falls within the predefined range set by the program, the robot will move forward or backward accordingly.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+ze+'"><ul><li><strong>Sensor Introduction</strong></li></ul><img loading="lazy" height="323" width="497" class="common_img" src="'+Ue+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Distance-Controlled%20Walking%20Program.zip">Distance-Controlled Walking Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+Re+'" style="width:70px;"></p><p>(2) Drag the &quot;<strong>02 Distance-Controlled Walking.sb3</strong>&quot; file from the same folder as this document into WonderCode.</p><img loading="lazy" height="370" width="1368" class="common_img" src="'+qe+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a &quot;Connection Successful&quot; message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+Se+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+Oe+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+Ie+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+Be+'"><ul><li><strong>Achieved Effect</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Avoid using the ultrasonic sensor to continuously detect objects that are extremely close.</p></section><p>Place a cardboard box in front of the ultrasonic sensor. When the distance is between 28 and 40 cm, the robot will move forward. When the distance is between 3 and 18 cm, the robot will move backward.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+l+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Distance-Controlled%20Walking%20Program.zip">Distance-Controlled Walking Program</a></p><p>(1) Initialize the Tonybot&#39;s posture and set the initial action.</p><img loading="lazy" height="231" width="571" class="common_img" src="'+Pe+'"><p>(2) In the main program, initiate an infinite loop. The Distance variable stores the current measurement between the sensor and the obstacle. When the step variable is set to 0, the program will proceed with the subsequent actions. If the measured distance to the obstacle meets the specified condition, the robot will execute either a forward or backward movement.</p><img loading="lazy" height="374" width="740" class="common_img" src="'+xe+'"><p>(3) When the step variable is 1, if the detected distance is greater than 3 and less than 18, or if the have_move variable equals 1, then initialize the have_move variable and run action group 22 once. If the conditions are not met, update the step to 3.</p><img loading="lazy" height="289" width="858" class="common_img" src="'+Ze+'"><h3 id="_5-2-4-treasure-hunt-project" tabindex="-1">5.2.4 Treasure Hunt Project <a class="header-anchor" href="#_5-2-4-treasure-hunt-project" aria-label="Permalink to &quot;5.2.4 Treasure Hunt Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>In this lesson, the robot&#39;s servo controlling the ultrasonic sensor will rotate back and forth. When the set conditions are met, the robot will turn in the corresponding direction.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+Ye+'"><ul><li><strong>Sensor Introduction</strong></li></ul><img loading="lazy" height="323" width="497" class="common_img" src="'+Me+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Treasure%20Hunt%20Program.zip">Treasure Hunt Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+Ve+'"></p><p>(2) Drag the <strong>&quot;02 Treasure Hunt.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="463" width="1385" class="common_img" src="'+je+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a <strong>&quot;Connection Successful&quot;</strong> message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+ke+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+Qe+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+Le+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+De+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>The servo beneath the ultrasonic sensor will first rotate back and forth, simultaneously measuring the distance between the robot and any obstacles. The distances will then be compared.</p><p>If the distance on one side is relatively closer to the robot, the robot will turn in the corresponding direction. In other words, if the distance on the left is shorter, the robot will turn left; if the distance on the right is shorter, the robot will turn right.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+c+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Treasure%20Hunt%20Program.zip">Treasure Hunt Program</a></p><p>(1) Initialize the posture of Tonybot and set the initial actions.</p><img loading="lazy" height="218" width="582" class="common_img" src="'+Ne+'"><p>(2) In the main program, declare the required global variables. Then, the program enters an infinite loop, continuously reading distance data from the ultrasonic sensor and performing corresponding actions based on different conditions.</p><img loading="lazy" height="117" width="650" class="common_img" src="'+Xe+'"><p><strong>First iteration (step = 0):</strong></p><p>① The program executes the logic for step = 0, using the measured distance to control the ultrasonic RGB module, which lights up in different colors depending on the distance.</p><p>② If the forward distance to the treasure box falls within a moderate range (30–300), the logic for step = 1 is executed (while step remains 0). If the distance is too large, step is set to 1, prompting the program in the next loop to search for the direction closest to the treasure box.</p><img loading="lazy" height="363" width="639" class="common_img" src="'+He+'"><p><strong>Second iteration (step = 1):</strong></p><p>① The program rotates the servo to detect the distance from four directions: 45° (front-left), 0° (left), 145° (front-right), and 180° (right).</p><p>② It then updates step to 2, allowing the program to proceed to directional decision-making in the next loop.</p><img loading="lazy" height="595" width="677" class="common_img" src="'+We+'"><p><strong>Third iteration (step = 2):</strong></p><p>① The program first processes and normalizes the distance values. If the sensor cannot detect the treasure box in a given direction (returns 0), that direction is treated as having an infinite distance, standardized to 9999.</p><p>② It then compares the distances from all directions to determine the shortest path to the treasure box. If the closest direction is on the left, the RGB module lights up blue; if on the right, it lights up red. The robot then performs a series of turns to align itself with the selected direction.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If the forward direction still yields the shortest distance despite being large, the robot will not perform any turning motion. In this case, the RGB light will remain green, as set during step = 0.</p></section><p>(3) Through this three-step cycle, the function’s complete detection and decision-making process is executed.</p><img loading="lazy" height="493" width="965" class="common_img" src="'+Ke+'"><img loading="lazy" height="502" width="882" class="common_img" src="'+Fe+'"><p>(4) In this code block, once step is updated to 2, the program evaluates the conditions and executes the corresponding actions—such as changing the color of the ultrasonic RGB light and triggering Action Group 34.</p><img loading="lazy" height="254" width="956" class="common_img" src="'+Je+'"><ul><li><strong>Function Extension</strong></li></ul><p>(1) Adjusting the Detection Range</p><p>① To modify the detection range, simply update the code within the highlighted section, as shown below:</p><img loading="lazy" height="335" width="825" class="common_img" src="'+Ge+'"><p>② When the detected distance between an object and the robot is greater than 3 cm but less than 35 cm, the system identifies the presence of a &quot;treasure box&quot; and triggers the treasure-hunting action. You can adjust the detection range by changing the condition in the distance check, as shown below:</p><img loading="lazy" height="335" width="756" class="common_img" src="'+_e+'"><p>(2) Modifying the Turning Conditions</p><p>① To adjust the turning conditions, update the code in the specified section of the program, as illustrated below:</p><img loading="lazy" height="866" width="960" class="common_img" src="'+$e+'"><p>② The program first evaluates the 5 measured directions and determines which one has the shortest distance. It then checks if this distance is within the defined detection range. If it is, the robot will perform the corresponding turning action.</p><img loading="lazy" height="257" width="935" class="common_img" src="'+to+'"><p>③ To modify the detection range, you can adjust the distance values in each directional check. For example, when the left side is the closest and the distance is under 400, the robot will turn left, as shown below:</p><img loading="lazy" height="259" width="946" class="common_img" src="'+eo+'"><h3 id="_5-2-5-low-altitude-navigation-project" tabindex="-1">5.2.5 Low-Altitude Navigation Project <a class="header-anchor" href="#_5-2-5-low-altitude-navigation-project" aria-label="Permalink to &quot;5.2.5 Low-Altitude Navigation Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>When the ultrasonic sensor detects an obstacle ahead, the robot will move forward a short distance in a crouching posture. Afterward, it will return to an upright position and continue moving forward in its normal stance.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+oo+'"><ul><li><strong>Sensor Introduction</strong></li></ul><img loading="lazy" height="323" width="497" class="common_img" src="'+so+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Low-Altitude%20Navigation%20Program.zip">Low-Altitude Navigation Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+no+'" style="width:70px;"></p><p>(2) Drag the <strong>&quot;02 Low-Altitude Navigation.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="428" width="1385" class="common_img" src="'+io+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a &quot;<strong>Connection Successful</strong>&quot; message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+ao+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+ro+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+lo+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+co+'"><ul><li><strong>Achieved Effect</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Avoid using the ultrasonic sensor to continuously detect objects that are too close.</p></section><p>You can create a <strong>&quot;small tunnel&quot;</strong> using several cardboard boxes. As the robot moves forward, if the ultrasonic sensor detects an obstacle ahead, it will emit a beeping sound as an alert. Simultaneously, the RGB light on the ultrasonic sensor will change from green to red.</p><p>The robot will then move forward a short distance in a crouching posture. After passing through the obstacle, it will return to an upright position and continue moving forward in its normal stance.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+g+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Low-Altitude%20Navigation%20Program.zip">Low-Altitude Navigation Program</a></p><p>(1) Initialize the posture of Tonybot and set the initial actions.</p><img loading="lazy" height="210" width="615" class="common_img" src="'+go+'"><p>(2) Initialize global variables, such as distance (distance), step (step), DLC (distance threshold), DL (another distance threshold), and others.</p><p>(3) Enter a loop to continuously read the distance values from the ultrasonic sensor. Based on the distance values and the current step (step), execute the corresponding actions and update the step accordingly.</p><p>(4) Within the loop, the robot executes different movement behaviors based on the current step value:</p><p><strong>First Iteration (step = 0):</strong></p><p>①　The program runs the logic for step = 0. If the measured distance is greater than the predefined threshold (i.e., no obstacle is detected and the distance value is 0), the robot executes a specific action group, lights up green, and transitions to the logic for the second iteration on the next loop cycle.</p><p>②　If the measured distance is less than the threshold, the robot remains in the step = 0 logic branch during the next loop cycle.</p><img loading="lazy" height="258" width="564" class="common_img" src="'+ho+'"><p><strong>Second Iteration (step = 1):</strong></p><p>①　If, during the time between the previous and current iterations, the newly measured distance falls below the threshold, the robot performs two action groups, lights up red, and activates the buzzer as an alert. It then shifts to a low-stance standing position and proceeds to step = 2 in the next cycle.</p><p>②　If the distance remains above the threshold, the robot performs a high-stance walking action and stays in the step = 1 branch in the following loop.</p><img loading="lazy" height="589" width="612" class="common_img" src="'+mo+'"><p><strong>Third Iteration (step = 2):</strong></p><p>①　If the newly measured distance is still below the threshold, the robot executes two action groups, lights up blue, and transitions from a stationary low stance to low-stance forward movement.</p><p>②　If the distance exceeds the threshold, the robot maintains its low-stance standing position and remains in the step = 2 logic on the next cycle.</p><img loading="lazy" height="290" width="582" class="common_img" src="'+po+'"><p><strong>Fourth Iteration (step = 3):</strong></p><p>①　The robot first performs a low-stance standing action to stop any ongoing low-stance movement, then transitions to a high-stance standing state.</p><p>②　On the next loop cycle, the program resets and returns to the logic branch for step = 0.</p><img loading="lazy" height="301" width="594" class="common_img" src="'+Ao+'"><h3 id="_5-2-6-head-shaking-obstacle-avoidance" tabindex="-1">5.2.6 Head-Shaking Obstacle Avoidance <a class="header-anchor" href="#_5-2-6-head-shaking-obstacle-avoidance" aria-label="Permalink to &quot;5.2.6 Head-Shaking Obstacle Avoidance&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>When the ultrasonic sensor detects an obstacle ahead, the robot will move to avoid the obstacle, implementing intelligent obstacle avoidance.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+uo+'"><ul><li><strong>Sensor Introduction</strong></li></ul><img loading="lazy" height="323" width="497" class="common_img" src="'+bo+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Head-Shaking%20Obstacle%20Avoidance%20Program.zip">Head-Shaking Obstacle Avoidance Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+wo+'" style="width:70px;"></p><p>(2) Drag the <strong>&quot;Head-Shaking Obstacle Avoidance.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="450" width="1384" class="common_img" src="'+fo+'"><p>(3) In the menu bar, click on &quot;<strong>Connect</strong>&quot; and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a &quot;Connection Successful&quot; message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+yo+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+vo+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" class="common_img" src="'+To+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+Co+'"><ul><li><strong>Achieved Effect</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Avoid using the ultrasonic sensor to continuously detect objects that are too close.</p></section><p>When an obstacle is detected ahead, the robot will stop and perform a head-shaking motion to check for obstacles on the left and right. Based on the detection results, the robot will turn in the direction where no obstacle is present and continue moving forward.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+d+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Head-Shaking%20Obstacle%20Avoidance%20Program.zip">Head-Shaking Obstacle Avoidance Program</a></p><p>(1) Initialize the Tonybot&#39;s posture and set the initial motion.</p><img loading="lazy" height="227" width="641" class="common_img" src="'+Eo+'"><p>(2) Execute specific actions to avoid obstacles based on the distance measurements obtained from the ultrasonic sensor.</p><img loading="lazy" height="689" width="813" class="common_img" src="'+s+'"><h3 id="_5-2-7-fall-and-recover-program-project" tabindex="-1">5.2.7 Fall and Recover Program Project <a class="header-anchor" href="#_5-2-7-fall-and-recover-program-project" aria-label="Permalink to &quot;5.2.7 Fall and Recover Program Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>This section utilizes an accelerometer to monitor the current state. Upon detecting a fall, the robot will initiate the action to stand up.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+zo+'"><ul><li><strong>Sensor Introduction</strong></li></ul><p>This section makes use of the onboard QMI8658 motion sensor, which has a wide range of applications, including handheld gaming devices, 3D controllers, and portable navigation systems.</p><img loading="lazy" height="146" width="185" class="common_img" src="'+Uo+'"><p>It integrates a 3-axis MEMS gyroscope, a 3-axis MEMS accelerometer, and an expandable Digital Motion Processor (DMP).</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Fall%20and%20Recover%20Program.zip">Fall and Recover Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+Ro+'" style="width:70px;"></p><p>(2) Drag the <strong>&quot;Fall and Recover.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="418" width="1382" class="common_img" src="'+qo+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a <strong>&quot;Connection Successful&quot;</strong> message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+So+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+Oo+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+Io+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+Bo+'"><ul><li><strong>Achieved Effect</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>In the fall and recover mode, when the robot is powered on or restarted, the IMU will initialize. Wait for the &#39;beep&#39; sound to confirm that initialization is complete.</p></section><p>After turning on the robot, place it flat either on its front or back. After a brief moment, the robot will automatically perform the standing action. (The standing action differs depending on whether the robot is placed face up or face down.)</p><img loading="lazy" height="360" width="640" class="common_img" src="'+h+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Fall%20and%20Recover%20Program.zip">Fall and Recover Program</a></p><p>(1) Initialize the Tonybot&#39;s posture and set the initial action.</p><img loading="lazy" height="287" width="718" class="common_img" src="'+Po+'"><p>(2) Read the IMU sensor&#39;s angles. By obtaining the roll angle values, detect whether the robot is in a <strong>&quot;fallen&quot;</strong> state, and execute the standing action group based on this status.</p><img loading="lazy" height="689" width="813" class="common_img" src="'+s+'"><h3 id="_5-2-8-smart-fan-project" tabindex="-1">5.2.8 Smart Fan Project <a class="header-anchor" href="#_5-2-8-smart-fan-project" aria-label="Permalink to &quot;5.2.8 Smart Fan Project&quot;">​</a></h3><ul><li><strong>Sensor Installation &amp; Wiring</strong></li></ul><img loading="lazy" height="600" width="1200" class="common_img" src="'+m+'"><img loading="lazy" class="common_img" src="'+p+'"><ul><li><strong>Project Introduction</strong></li></ul><p>This section utilizes a glowy ultrasonic sensor to measure the distance to obstacles. Based on the detected distance, the arm is raised, the fan is activated, and the color of the ultrasonic RGB LED changes accordingly.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+xo+'"><ul><li><strong>Sensor Introduction</strong></li></ul><p><strong>(1) Glowy Ultrasonic Sensor</strong></p><img loading="lazy" height="323" width="497" class="common_img" src="'+Zo+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><p><strong>(2) Fan Module</strong></p><p>The fan module is a sensor that operates without the need for an external motor driver board, utilizing PWM (pulse-width modulation) to control its movement. The direction of the fan&#39;s rotation is managed by PWM pulse waveforms in both directions, while the fan speed is adjustable by modifying the duty cycle of the PWM signal.</p><img loading="lazy" height="593" width="574" class="common_img" src="'+Yo+'" style="width:300px;"><p>For module installation and wiring, please refer to the section 1 in the same folder.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Smart%20Fan%20Program.zip">Smart Fan Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+Mo+'" style="width:70px;"></p><p>(2) Drag the <strong>&quot;Smart Fan.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="426" width="1382" class="common_img" src="'+Vo+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a <strong>&quot;Connection Successful&quot;</strong> message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+jo+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+ko+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+Qo+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+Lo+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>Slowly move the object closer to the glowy ultrasonic sensor. If the distance is less than 300mm, the robot will extend its right hand and activate the fan. If the distance exceeds 300mm, the right hand will lower, and the fan will be deactivated.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+A+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Smart%20Fan%20Program.zip">Smart Fan Program</a></p><p>(1) Initialize the Tonybot&#39;s posture, set the initial action, and initialize the ultrasonic RGB lights.</p><img loading="lazy" height="249" width="682" class="common_img" src="'+Do+'"><p>(2) Infinite loop:</p><p>Within the loop, different actions are performed based on the distance between the device and obstacles, with movements triggered by the angle. For example, when the distance is less than 30 cm, the ultrasonic RGB lights will turn green. Then, Servo 16 will execute an action lasting 500 ms, followed by a 0.5-second pause before the loop repeats.</p><img loading="lazy" height="727" width="888" class="common_img" src="'+No+'"><h3 id="_5-2-9-touch-control-project" tabindex="-1">5.2.9 Touch Control Project <a class="header-anchor" href="#_5-2-9-touch-control-project" aria-label="Permalink to &quot;5.2.9 Touch Control Project&quot;">​</a></h3><ul><li><strong>Sensor Installation &amp; Wiring</strong></li></ul><img loading="lazy" height="600" width="1200" class="common_img" src="'+u+'"><img loading="lazy" class="common_img" src="'+b+'"><ul><li><strong>Project Introduction</strong></li></ul><p>Touch the capacitive pad on the touch sensor, and Tonybot will perform a bowing motion.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="470" width="1268" class="common_img" src="'+Xo+'"><ul><li><strong>Sensor Introduction</strong></li></ul><p>The touch sensor operates based on capacitive sensing technology, detecting the presence of human skin or metal through its gold-plated contact surface.</p><p>When no human or metal is in contact with the surface, the signal output is high. Upon contact with a human or metal, the signal output becomes low. Additionally, the sensor can detect contact through materials such as plastic or paper. The sensitivity of detection is influenced by the size of the contact surface and the thickness of the covering material.</p><img loading="lazy" height="221" width="527" class="common_img" src="'+Ho+'" style="width:300px;"><p>For module installation and wiring, please refer to the section 1 in the same directory.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Touch%20Control%20Program.zip">Touch Control Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+Wo+'" style="width:70px;"></p><p>(2) Drag the &quot;<strong>Touch Control.sb3</strong>&quot; file from the same folder as this document into WonderCode.</p><img loading="lazy" height="429" width="1382" class="common_img" src="'+Ko+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a <strong>&quot;Connection Successful&quot;</strong> message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+Fo+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+Jo+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+Go+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+_o+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>Tap the capacitive pad on the touch sensor, and Tonybot will perform a bowing motion.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+w+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Touch%20Control%20Program.zip">Touch Control Program</a></p><p>(1) Initialize the touch sensor interface and configure Tonybot&#39;s initial posture.</p><img loading="lazy" height="258" width="689" class="common_img" src="'+$o+'"><p>(2) If the touch sensor is pressed and the enter_flag is 0, set enter_flag to 1 and execute action group 10 once. If the touch sensor is not pressed, set enter_flag to 0, wait for 0.05 seconds, and then continue repeating the process.</p><img loading="lazy" height="391" width="725" class="common_img" src="'+ts+'"><ul><li><strong>Function Extension</strong></li></ul><p>Here&#39;s a clear example of how to change the action group from bowing to twisting:</p><p>Find the part of the code that executes the action group. Replace the reference to action group 10 (bowing) with action group 50 (twisting). This modification will allow the twisting action group to be triggered by the touch sensor instead of the bowing action.</p><img loading="lazy" height="397" width="783" class="common_img" src="'+es+'"><ul><li><strong>FAQ</strong></li></ul><p>Q: Why isn&#39;t the touch sensor responding after uploading the code?</p><p>A: Please ensure that the touch sensor is connected to the correct port. For proper connection, refer to section 2.3.</p><h3 id="_5-2-10-temperature-and-humidity-detection-project" tabindex="-1">5.2.10 Temperature and Humidity Detection Project <a class="header-anchor" href="#_5-2-10-temperature-and-humidity-detection-project" aria-label="Permalink to &quot;5.2.10 Temperature and Humidity Detection Project&quot;">​</a></h3><ul><li><strong>Sensor Installation &amp; Wiring</strong></li></ul><img loading="lazy" height="600" width="1200" class="common_img" src="'+f+'"><img loading="lazy" class="common_img" src="'+y+'"><ul><li><strong>Project Introduction</strong></li></ul><p>Once the mode is activated, Tonybot will monitor the temperature and humidity, and display the data on the matrix module.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+os+'"><ul><li><strong>Sensor Introduction</strong></li></ul><p>(1) Temperature and Humidity Sensor</p><p>This sensor detects the temperature and humidity of the environment and provides accurate readings.</p><img loading="lazy" height="184" width="343" class="common_img" src="'+ss+'" style="width:300px;"><p>The AHT10 module converts the air&#39;s temperature and humidity into digital signals, which are then sent to the control board via I2C communication.</p><p>(2) LED Dot Matrix Module</p><p>The LED dot matrix module uses an 8x8 LED display, known for its high brightness, flicker-free display, and easy wiring. It can display numbers, text, patterns, and more. The module consists of two red 8x8 LED arrays and is controlled by the driver chip TM640B, enabling full control of the dot matrix screen.</p><img loading="lazy" height="296" width="659" class="common_img" src="'+ns+'" style="width:300px;"><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Temperature%20and%20Humidity%20Detection%20Program.zip">Temperature and Humidity Detection Program</a></p><p>(1) Open the <strong>WonderCode</strong> software <img loading="lazy" height="87" width="85" src="'+is+'" style="width:70px;">.</p><p>(2) Locate the <strong>&quot;02 temp_humidity_detection.sb3&quot;</strong> file in the same directory as this document, then drag and drop it into <strong>WonderCode</strong>.</p><img loading="lazy" height="469" width="1384" class="common_img" src="'+as+'"><p>(3) In the menu bar, click <strong>&quot;Connect&quot;</strong>, then select the appropriate <strong>COM port</strong> (e.g., COM7 in this example). A <strong>&quot;Connection Successful&quot;</strong> message will appear once the connection is established.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+rs+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+ls+'"><p>(4) Click <img loading="lazy" height="41" width="47" src="'+cs+'"> on the right to transfer the program to <strong>Tonybot</strong>. Wait for the confirmation message indicating a successful upload.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+gs+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>Once the temperature and humidity are detected, the dot matrix module will display them individually.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+v+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the dot matrix module interface and set Tonybot to its default posture.</p><img loading="lazy" height="257" width="666" class="common_img" src="'+ds+'"><p>(2) First, obtain the temperature reading from the temperature and humidity sensor and display it on the dot matrix module.</p><img loading="lazy" height="301" width="771" class="common_img" src="'+hs+'"><p>(3) Then, obtain the humidity reading from the sensor and display it on the dot matrix module.</p><img loading="lazy" height="285" width="668" class="common_img" src="'+ms+'"><h2 id="_5-3-voice-interaction-course" tabindex="-1">5.3 Voice Interaction Course <a class="header-anchor" href="#_5-3-voice-interaction-course" aria-label="Permalink to &quot;5.3 Voice Interaction Course&quot;">​</a></h2><h3 id="_5-3-1-wonderecho-introduction-assembly" tabindex="-1">5.3.1 WonderEcho Introduction &amp; Assembly <a class="header-anchor" href="#_5-3-1-wonderecho-introduction-assembly" aria-label="Permalink to &quot;5.3.1 WonderEcho Introduction &amp; Assembly&quot;">​</a></h3><ul><li><strong>Sensor Installation &amp; Wiring</strong></li></ul><img loading="lazy" height="600" width="1200" class="common_img" src="'+T+'"><ul><li><strong>Introduction and Working Principle</strong></li></ul><p>(1) Introduction</p><img loading="lazy" height="290" width="556" class="common_img" src="'+ps+'" style="width:300px;"><p>The voice interaction module is built on embedded voice recognition technology. It consists of a voice recognition chip and supporting circuits, designed for seamless communication with the main control chip. This module enables both voice recognition and voice playback functionalities. Developers can easily integrate it into their products to enable voice interaction capabilities.</p><p>(2) Working Principle</p><p>The module communicates via I2C and functions as a slave device, allowing communication with a master device. When the microphone on the module detects sound, it processes the audio and sends the result back to the master device.</p><p>The module operates in a keyword wake-up mode, requiring a specific trigger word to initiate recognition. By default, the wake-up keyword is &quot;<strong>Hello Hiwonder</strong>&quot;. Once recognition is complete, if further recognition is required, the module must be re-activated by the wake-up keyword after a 15-second delay.</p><ul><li><strong>Interface Description</strong></li></ul><p><strong>Type-C Interface</strong>: Used for powering the module and for firmware programming.</p><p><strong>I2C Interface</strong>: Used for communication with host devices.</p><img loading="lazy" height="413" width="856" class="common_img" src="'+As+'" style="width:300px;"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>PIN</strong></th><th style="text-align:center;"><strong>Function Description</strong></th></tr></thead><tbody><tr><td style="text-align:center;">5V</td><td style="text-align:center;">Power input</td></tr><tr><td style="text-align:center;">GND</td><td style="text-align:center;">Power ground</td></tr><tr><td style="text-align:center;">SDA</td><td style="text-align:center;">I2C data cable</td></tr><tr><td style="text-align:center;">SCL</td><td style="text-align:center;">I2C clock cable</td></tr></tbody></table><ul><li><strong>Important Notes</strong></li></ul><p>(1) Ensure the voltage does not exceed the rated range during use.</p><p>(2) The environment should be quiet, as noise may impact recognition performance.</p><p>(3) When speaking the trigger phrase, make sure your voice is clear and loud, and avoid speaking too quickly. It is recommended to maintain a distance of no more than 5 meters from the module.</p><h3 id="_5-3-2-distance-ranging-announcement-project" tabindex="-1">5.3.2 Distance Ranging &amp; Announcement Project <a class="header-anchor" href="#_5-3-2-distance-ranging-announcement-project" aria-label="Permalink to &quot;5.3.2 Distance Ranging &amp; Announcement Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>This section utilizes the glowy ultrasonic module to measure the distance to an obstacle. Based on the detected distance, it controls the voice interaction module to announce messages and triggers the robot to perform specific action groups.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="473" width="1268" class="common_img" src="'+us+'"><ul><li><strong>Sensor Introduction</strong></li></ul><p>(1) Glowy Ultrasonic Sensor</p><img loading="lazy" height="323" width="497" class="common_img" src="'+bs+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><p>(2) Voice Interaction Module</p><img loading="lazy" height="221" width="420" class="common_img" src="'+ws+'" style="width:300px;"><p>The voice interaction module is built on embedded voice recognition technology. It consists of a voice recognition chip and supporting circuits, designed for seamless communication with the main control chip. This module enables both voice recognition and voice playback functionalities. Developers can easily integrate it into their products to enable voice interaction capabilities.</p><p>For instructions on module installation and wiring, please refer to assembly guide saved in the same directory.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Distance%20Ranging%20&amp;%20Announcement%20Program.zip">Distance Ranging &amp; Announcement Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+fs+'" style="width:70px;"></p><p>(2) Drag the &quot;Distance Ranging &amp; Result Broadcasting.sb3&quot; file from the same folder as this document into WonderCode.</p><img loading="lazy" height="436" width="1382" class="common_img" src="'+ys+'"><p>(3) In the menu bar, click on &quot;<strong>Connect</strong>&quot; and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a &quot;<strong>Connection Successful</strong>&quot; message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+vs+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+Ts+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+Cs+'" style="width:70px;"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+Es+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>Once the Tonybot is powered on, slowly move the object towards the glowy ultrasonic sensor. When the distance falls below 200mm, action group 9 will be triggered, and a greeting will be broadcast: &quot;<strong>Hello, welcome</strong>&quot;.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+C+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Distance%20Ranging%20&amp;%20Announcement%20Program.zip">Distance Ranging &amp; Announcement Program</a></p><p>(1) Initialize the posture of the Tonybot and the voice module interface.</p><img loading="lazy" height="259" width="652" class="common_img" src="'+zs+'"><p>(2) Set the variable distance to the distance between the glowy ultrasonic sensor and the obstacle. If this distance is less than 20, set have_move to 1 and change the color of the two ultrasonic sensor lights to blue. Then, execute action group 9 once, wait 0.5 seconds, broadcast the phrase via the voice module, wait for 2 seconds, and repeat the cycle.</p><img loading="lazy" height="371" width="727" class="common_img" src="'+Us+'"><p>(3) If the distance variable is greater than 20, set have_home to 1, change the color of the ultrasonic sensor lights to green, execute action group 0 once, wait 0.1 seconds, and continue looping through the previous code block.</p><img loading="lazy" height="277" width="679" class="common_img" src="'+Rs+'"><h3 id="_5-3-3-human-robot-interaction-project" tabindex="-1">5.3.3 Human-Robot Interaction Project <a class="header-anchor" href="#_5-3-3-human-robot-interaction-project" aria-label="Permalink to &quot;5.3.3 Human-Robot Interaction Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>The voice interaction module recognizes trigger phrases, which then control the Tonybot to execute the corresponding actions.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+qs+'"><ul><li><strong>Sensor Introduction</strong></li></ul><img loading="lazy" height="221" width="420" class="common_img" src="'+Ss+'" style="width:300px;"><p>The voice interaction module is built on embedded voice recognition technology. It consists of a voice recognition chip and supporting circuits, designed for seamless communication with the main control chip. This module enables both voice recognition and voice playback functionalities. Developers can easily integrate it into their products to enable voice interaction capabilities.</p><p>For instructions on module installation and wiring, please refer to assembly guide saved in the same directory.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Human-Robot%20Interaction%20Program.zip">Human-Robot Interaction Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+Os+'" style="width:70px;"></p><p>(2) Drag the <strong>&quot;Human-Robot Interaction.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="455" width="1381" class="common_img" src="'+Is+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a <strong>&quot;Connection Successful&quot;</strong> message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+Bs+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+Ps+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+xs+'" style="width:70px;"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+Zs+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>Activate the voice interaction module by saying <strong>&quot;Hello Hiwonder&quot;</strong>. Once activated, the robot will perform the corresponding actions based on the trigger phrases listed below.</p><table tabindex="0"><thead><tr><th>NO.</th><th>Command Phrase</th><th>Corresponding Action</th></tr></thead><tbody><tr><td>36</td><td>HELLO</td><td>Bow</td></tr><tr><td>37</td><td>INTRODUCE-YOURSELF</td><td>Say hello</td></tr><tr><td>38</td><td>SHOW-A-SKIII</td><td>Spread arms</td></tr><tr><td>41</td><td>DIVE-FORWARD</td><td>Go forward</td></tr><tr><td>30</td><td>SHAKE-IT-OFF</td><td>Control servo to rotate</td></tr></tbody></table><img loading="lazy" height="360" width="640" class="common_img" src="'+E+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Human-Robot%20Interaction%20Program.zip">Human-Robot Interaction Program</a></p><p>(1) Initialize the posture of the Tonybot, the voice module interface, and configure the flags for the buttons and actions.</p><img loading="lazy" height="264" width="716" class="common_img" src="'+Ys+'"><p>(2) Initialize the result variable. When the value received from the voice module is 26 (which corresponds to &quot;<strong>Hello</strong>&quot;, and so on), execute action group 10 once. If the value is 27, execute action group 48 once. If the value is 28, execute action group 17 once.</p><img loading="lazy" height="615" width="839" class="common_img" src="'+Ms+'"><p>(3) When the value is 29, wait for one second, then execute action group 18 once, followed by action group 21 three times. Afterward, execute action group 18 once more, followed by action group 19 once. The timeout for this sequence is the total duration required for action group 18, which is 2000ms.</p><img loading="lazy" height="402" width="831" class="common_img" src="'+Vs+'"><p>(4) If the value received is 30, Tonybot will trigger the servo motor to perform the corresponding action after a 0.5-second delay. Once the action is completed, the servo will be disabled, and the main program will restart the cycle.</p><img loading="lazy" height="545" width="563" class="common_img" src="'+js+'"><ul><li><strong>Function Extension</strong></li></ul><p>In the program, we can add new entries and perform new actions. For example, to add the <strong>&quot;sit-up&quot;</strong> action:</p><p>(1) Add the <strong>&quot;if&quot;</strong> statement block at the end of the program.</p><img loading="lazy" height="420" width="1064" class="common_img" src="'+ks+'"><p>(2) Set the condition to result = 114.</p><img loading="lazy" height="276" width="708" class="common_img" src="'+Qs+'"><p>(3) If the condition is true, execute Action Group 8 once, which corresponds to the <strong>&quot;sit-up&quot;</strong> action.</p><img loading="lazy" height="259" width="640" class="common_img" src="'+Ls+'"><ul><li><strong>FAQ</strong></li></ul><p>**Q:**The voice interaction module is not responding.</p><p><strong>A:</strong> Please check if you have activated the module by saying &quot;<strong>Hello Hiwonder</strong>&quot; If the module is already activated, verify that it is connected correctly.</p><h3 id="_5-3-4-voice-control-project" tabindex="-1">5.3.4 Voice Control Project <a class="header-anchor" href="#_5-3-4-voice-control-project" aria-label="Permalink to &quot;5.3.4 Voice Control Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>In this section, the voice interaction module is used to control Tonybot&#39;s movements, including moving forward, backward, and turning left or right.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+Ds+'"><ul><li><strong>Sensor Introduction</strong></li></ul><img loading="lazy" height="221" width="420" class="common_img" src="'+Ns+'" style="width:300px;"><p>The voice interaction module is built on embedded voice recognition technology. It consists of a voice recognition chip and supporting circuits, designed for seamless communication with the main control chip. This module enables both voice recognition and voice playback functionalities. Developers can easily integrate it into their products to enable voice interaction capabilities.</p><p>For instructions on module installation and wiring, please refer to assembly guide saved in the same directory.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Voice%20Control%20Program.zip">Voice Control Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+Xs+'"></p><p>(2) Drag the <strong>&quot;Voice Control.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="572" width="1383" class="common_img" src="'+Hs+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a <strong>&quot;Connection Successful&quot;</strong> message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+Ws+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+Ks+'"><p>(4) Hit the <strong>&quot;Upload&quot;</strong> button <img loading="lazy" height="41" width="47" src="'+Fs+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+Js+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>To activate the voice recognition module, simply say &quot;<strong>Hello Hiwonder</strong>&quot; You can then use commands like &#39;move forward&#39;, &#39;move backward&#39;, &#39;turn left&#39; and &#39;turn right&#39; to control Tonybot&#39;s movements. For a complete list of available commands, please refer to the table below.</p><table tabindex="0"><thead><tr><th>Command Phrase</th><th>Returned Value</th><th>Command Phrase</th><th>Returned Value</th></tr></thead><tbody><tr><td>GO-STRAIGHT</td><td>0x01</td><td>GO-BACKWARD</td><td>0x02</td></tr><tr><td>TURN LEFT</td><td>0x03</td><td>TURN RIGHT</td><td>0x04</td></tr><tr><td>LEFT-FOOT-SHOOT</td><td>0x6E</td><td>TWIST</td><td>0x71</td></tr><tr><td>SIT-UP</td><td>0x72</td><td>BOW</td><td>0x73</td></tr><tr><td>SPREAD ARMS</td><td>0x74</td><td>WAVE HAND</td><td>0x75</td></tr><tr><td>MARCH-IN-PLACE</td><td>0x76</td><td>RIGHT-HOOK</td><td>0x7A</td></tr></tbody></table><img loading="lazy" height="360" width="640" class="common_img" src="'+z+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Voice%20Control%20Program.zip"> Voice Control Program</a></p><p>(1) Initialize Tonybot&#39;s posture and voice module, and set the flags for the buttons and actions.</p><img loading="lazy" height="264" width="654" class="common_img" src="'+Gs+'"><p>(2) Initialize the variable result. If the value received from the voice module is 113, execute action group 50 once. If the value is 114, execute action group 8 once.</p><img loading="lazy" height="384" width="659" class="common_img" src="'+_s+'"><p>(3) When the value received is 1, execute action group 18 once, followed by action group 21 three times. Then, execute action group 18 again once, and finally, execute action group 19 once. The total timeout duration should be set to 2000ms, which is the runtime of action group 18.</p><img loading="lazy" height="368" width="675" class="common_img" src="'+$s+'"><h3 id="_5-3-5-fall-recovery-project" tabindex="-1">5.3.5 Fall Recovery Project <a class="header-anchor" href="#_5-3-5-fall-recovery-project" aria-label="Permalink to &quot;5.3.5 Fall Recovery Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>After the robot falls, say the command &#39;fall recovery&#39; to make the robot stand up.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="473" width="1268" class="common_img" src="'+tn+'"><ul><li><strong>Sensor Introduction</strong></li></ul><img loading="lazy" height="221" width="420" class="common_img" src="'+en+'" style="width:300px;"><p>The voice interaction module is built on embedded voice recognition technology. It consists of a voice recognition chip and supporting circuits, designed for seamless communication with the main control chip. This module enables both voice recognition and voice playback functionalities. Developers can easily integrate it into their products to enable voice interaction capabilities.</p><p>For instructions on module installation and wiring, please refer to assembly guide saved in the same directory.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Fall%20Recovery%20Program.zip">Fall Recovery Program</a></p><p>(1) Open the WonderCode software <img loading="lazy" height="87" width="85" src="'+on+'" style="width:70px;"></p><p>(2) Drag the <strong>&quot;Fall Recovery.sb3&quot;</strong> file from the same folder as this document into WonderCode.</p><img loading="lazy" height="458" width="1383" class="common_img" src="'+sn+'"><p>(3) In the menu bar, click on <strong>&quot;Connect&quot;</strong> and select the correct COM port (e.g., COM7). Once the connection is successful, you&#39;ll see a &quot;<strong>Connection Successful</strong>&quot; message.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+nn+'"><img loading="lazy" height="55" width="176" class="common_img" src="'+an+'"><p>(4) Hit the Upload button <img loading="lazy" height="41" width="47" src="'+rn+'"> on the right to transfer the program to the Tonybot. Wait for the confirmation that the upload is complete.</p><img loading="lazy" height="353" width="660" class="common_img" src="'+ln+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>If the robot is in a fallen state, say &#39;Hello Hiwonder&#39; to activate the voice interaction module. Then, use the command &#39;fall recovery&#39; to make the robot stand up.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+U+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Fall%20Recovery%20Program.zip">Fall Recovery Program</a></p><p>(1) Initialize Tonybot&#39;s posture, voice module interface, and set the flags for buttons and actions. If the head servo fails and remains inactive for 6 seconds, the system will begin playing audio in the background.</p><img loading="lazy" height="322" width="802" class="common_img" src="'+cn+'"><p>(2) Initialize the variable angle with the value obtained from the IMU sensor. If the value is between -30 and 60, the system will play audio in the background. After waiting for one second, action group 102 will be executed once.</p><img loading="lazy" height="349" width="746" class="common_img" src="'+gn+'"><p>(3) If the value is between 120 and 140, the system will play audio in the background. After waiting for one second, action group 101 will be executed once. Finally, the program will wait for 0.05 seconds before looping back to continue the main program.</p><img loading="lazy" height="341" width="752" class="common_img" src="'+dn+'"><h2 id="_5-4-ai-vision-course" tabindex="-1">5.4 AI Vision Course <a class="header-anchor" href="#_5-4-ai-vision-course" aria-label="Permalink to &quot;5.4 AI Vision Course&quot;">​</a></h2><p id="anchor_4_4_1"></p><h3 id="_5-4-1-introduction-to-esp32s3-vision-module" tabindex="-1">5.4.1 Introduction to ESP32S3 Vision Module <a class="header-anchor" href="#_5-4-1-introduction-to-esp32s3-vision-module" aria-label="Permalink to &quot;5.4.1 Introduction to ESP32S3 Vision Module&quot;">​</a></h3><ul><li><p><strong>Assembly</strong></p><img loading="lazy" height="600" width="1200" class="common_img" src="'+R+'"></li><li><p><strong>Overview of the ESP32-S3</strong></p></li></ul><p>The ESP32-S3 Vision Module is a compact camera module that can function as a standalone system. It captures images with its built-in camera, processes the data using the ESP32 microcontroller, and wirelessly transmits it via Wi-Fi. With support for various communication protocols and low-power features, this module is widely used in a range of IoT applications.</p><img loading="lazy" height="349" width="505" class="common_img" src="'+hn+'" style="width:300px;"><p>(1) Specification</p><table class="docutils-nobg" border="1"><colgroup><col><col></colgroup><tbody><tr><td><strong>Parameter</strong></td><td><strong>Specification</strong></td></tr><tr><td>Size</td><td>59*43*17.5</td></tr><tr><td>Power Supply Range</td><td>4.75~5.25V</td></tr><tr><td>Operating Temperature</td><td>Ambient Temperature</td></tr><tr><td>Storage Environment</td><td>Ambient Temperature and Pressure</td></tr><tr><td>SPI Flash</td><td>Supports up to 16MB</td></tr><tr><td>RAM</td><td>512KB Internal + 16MB External PSRAM</td></tr><tr><td>Bluetooth</td><td>Suppport Bluetooth 5 and Bluetooth Mesh</td></tr><tr><td>WiFi</td><td>802.11 b/g/n</td></tr><tr><td>Supported Interfaces</td><td>UART、I2C</td></tr><tr><td>Serial Baud Rate</td><td>Default 115200</td></tr><tr><td>Image Output Format</td><td>JPEG (only supported by OV2640), BMP, Grayscale</td></tr><tr><td>Frequency Range</td><td>2412~2484MHz</td></tr><tr><td>Antenna Type</td><td>Onboard PCB Antenna</td></tr><tr><td>Transmit Power</td><td><p>802.11b:20.5 dBm(@11Mbps)</p><p>802.11g:18 dBm(@54Mbps)</p><p>802.11n:17 dBm(@MCS7)</p></td></tr><tr><td>Receive Sensitivity</td><td><p>802.11b:-88.5 dBm(@11Mbps)</p><p>802.11g:-76.2 dBm(@54Mbps)</p><p>802.11n:-74.2dBm(@MCS7 HT20)</p><p>-71.2dBm(@MCS7 HT40)</p></td></tr><tr><td>Power Consumption (assuming peripherals are on)</td><td><p>Active (RF On): TX: 285-355mA @ 3.3V RX:95-97mA@3.3V</p><p>Deep-sleep:8uA@5V</p><p>Modem-sleep:47.6-107.6mA@5V 240MHZ</p><p>Light-sleep:240uA@5V</p></td></tr><tr><td>Security</td><td>RSA/AES/SHA/HMAC/XTS-AES</td></tr></tbody></table><p><strong>Kind Reminder:</strong> The product specifications are theoretical values and are for reference only. Please rely on actual performance for precise details.</p><p>(2) Interface Description</p><img loading="lazy" height="547" width="1267" class="common_img" src="'+mn+'"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Interface Name</strong></th><th style="text-align:center;"><strong>Interface Description</strong></th></tr></thead><tbody><tr><td style="text-align:center;">USB Serial Port</td><td style="text-align:center;">Serial communication, firmware programming</td></tr><tr><td style="text-align:center;">Custom Button</td><td style="text-align:center;">Allows customization of the button event in code</td></tr><tr><td style="text-align:center;">IIC Interface</td><td style="text-align:center;">Secondary development interface, connects with the main controller</td></tr></tbody></table><ul><li><strong>ESP32-S3 Image Coordinate Framework</strong></li></ul><p>Here are a few important points to note about the module&#39;s image coordinate system:</p><p>(1) The origin is positioned at the center of the screen, not at the top-left corner.</p><p>(2) The Y-axis direction is opposite to that of a typical Cartesian coordinate system.</p><img loading="lazy" height="526" width="726" class="common_img" src="'+pn+'"><ul><li><strong>Important Notes:</strong></li></ul><p>(1) Ensure that the module is supplied with at least 5V 2A to avoid potential image distortion.</p><p>(2) The module comes with the default firmware pre-installed, which supports image transmission. No additional downloads are provided. If you need to reflash with different firmware, please proceed carefully.</p><h3 id="_5-4-2-image-transmission" tabindex="-1">5.4.2 Image Transmission <a class="header-anchor" href="#_5-4-2-image-transmission" aria-label="Permalink to &quot;5.4.2 Image Transmission&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The image transmission firmware is pre-installed at the factory. If you flash other firmware for different functionalities, you will need to reflash the image transmission firmware to enable this feature.</p></section><p>In this section, connect to the hotspot created by the ESP32-S3 vision module and visit the provided URL to view the real-time video feed from the camera.</p><ul><li><strong>Program Download</strong></li></ul><p>(1) ESP32-S3 Vision Module Firmware Download</p><p>① Connect the ESP32-S3 vision module to your computer using a Type-C data cable.</p><p>② Extract the ZIP file &quot;<a href="https://drive.google.com/drive/folders/1Jv6wpYZ8M8bFpxN0J3se8jfuXv7tMco2?usp=sharing" target="_blank" rel="noreferrer"><strong>Image Transmission Firmware &amp; Flash Tool/flash_download_tool_3.9.7</strong></a>&quot;, then double-click <strong>&quot;flash_download_tool_3.9.7.exe&quot;</strong> to open the program.</p><img loading="lazy" height="27" width="405" class="common_img" src="'+An+'"><p>③ In the opened window, configure it as shown below.</p><img loading="lazy" height="213" width="221" class="common_img" src="'+un+'"><p>④ In the flashing interface, click <img loading="lazy" height="21" width="263" src="'+bn+'"> to select the firmware file (&quot;<strong>Image Transmission Firmware &amp; Flash Tool/image_transmit.bin</strong>&quot;), then configure the settings according to the image below.</p><img loading="lazy" height="26" width="407" class="common_img" src="'+wn+'"><img loading="lazy" height="678" width="426" class="common_img" src="'+fn+'"><p>⑤ Choose the correct port number (do not select COM1, as this will cause the flashing to fail).</p><p>⑥ Click <strong>&quot;ERASE&quot;</strong> to erase the existing firmware (this step is essential), then click &quot;<strong>START</strong>&quot; to begin the flashing process.</p><img loading="lazy" height="150" width="422" class="common_img" src="'+yn+'"><p>⑦ Wait for a completion message to appear.</p><img loading="lazy" height="150" width="422" class="common_img" src="'+vn+'"><p>⑧ Once flashing is complete, disconnect the Type-C data cable and restart the device.</p><p>(2) Program Download</p><p><a href="../_static/source_code/04/Image%20Transmission%20Scratch%20Example.zip">Image Transmission Scratch Example.sb3</a></p><p>① Open the program file <strong>&quot;03 Image Transmission Scratch Example.sb3&quot;</strong> located in the same folder as this document in the WonderCode programming software.</p><img loading="lazy" height="24" width="423" class="common_img" src="'+Tn+'"><p>② Power on the device and connect it to the computer via the Type-C data cable.</p><p>③ Click the &quot;<strong>Connect</strong>&quot; button and select the corresponding port.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+Cn+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port number may vary depending on the computer&#39;s actual connection. For example, the port number used in this section is &quot;<strong>COM4</strong>&quot;. However, do not select &quot;<strong>COM1</strong>&quot;, as it is typically reserved for system communication.</p></section><p>④ When the device successfully pairs with the software, a successful connection message will appear.</p><img loading="lazy" height="55" width="176" class="common_img" src="'+En+'"><ul><li><strong>Device Connection</strong></li></ul><p>(1) Power on the device (ensure the vision module has been installed on the robot according to the instructions in &quot;<strong><a href="https://docs.hiwonder.com/projects/Tonybot/en/latest/docs/6.Arduino_programming_projects.html#overview-and-installation-of-esp32s3-vision-module" target="_blank" rel="noreferrer">6.4.1 Overview and Installation of ESP32S3 Vision Module</a></strong>&quot; before powering it on).</p><p>(2) Locate and connect to the hotspot generated by the module: <strong>HW_ESP32S3CAM</strong>.</p><img loading="lazy" height="184" width="354" class="common_img" src="'+zn+'"><img loading="lazy" height="133" width="354" class="common_img" src="'+Un+'"><p>(3) Image Transmission Implementation</p><p>Open a browser (this works on both mobile and PC browsers; we&#39;ll use a PC as an example) and enter &quot;<strong>192.168.5.1</strong>&quot; in the address bar, then press Enter. On the resulting page, click <img loading="lazy" height="28" width="113" src="'+Rn+'"> to access the camera&#39;s live transmission interface.</p><img loading="lazy" height="794" width="1346" class="common_img" src="'+qn+'"><h3 id="_5-4-3-color-recognition-project" tabindex="-1">5.4.3 Color Recognition Project <a class="header-anchor" href="#_5-4-3-color-recognition-project" aria-label="Permalink to &quot;5.4.3 Color Recognition Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>Tonybot, equipped with the ESP32-S3 vision module, can recognize red, green, and blue objects, while also controlling the RGB lights and displaying information on the dot matrix display.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="470" width="1268" class="common_img" src="'+Sn+'"><ul><li><strong>Module Introduction</strong></li></ul><p>(1) ESP32-S3 Vision Module</p><img loading="lazy" height="349" width="505" class="common_img" src="'+On+'" style="width:300px;"><p>The ESP32-S3 Vision Module is a compact camera module that can function as a standalone system. It captures images with its built-in camera, processes the data using the ESP32 microcontroller, and wirelessly transmits it via Wi-Fi. With support for various communication protocols and low-power features, this module is widely used in a range of IoT applications.</p><p>To get the detailed installation guide, please refer to &#39;<a href="#anchor_4_4_1"><strong>4.4.1 Overview and Installation of ESP32S3 Vision Module</strong></a>&#39;.</p><p>(2) LED Dot Matrix Module</p><p>The LED dot matrix module features a high-brightness display, flicker-free operation, and easy wiring. It is capable of displaying numbers, text, graphics, and other content. The module consists of two 8x8 red LED matrices, controlled by the TM640B driver chip, enabling full control of the display.</p><img loading="lazy" height="296" width="659" class="common_img" src="'+In+'" style="width:300px;"><p>For installation and wiring details, please refer to &quot;<strong>01 Dot Matrix Display Installation</strong>&quot; in this directory.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/ESP32S3%20Color%20Recognition%20Example.zip">ESP32S3 Color Recognition Example</a></p><p>(1) ESP32-S3 Vision Module Program Download</p><p>① Connect the ESP32-S3 to your computer using a Type-C data cable.</p><p>② Open the program file <strong>&quot;ESP32S3 Color Recognition Example/ ESP32S3_ColorDetection/ ESP32S3_ColorDetection.ino&quot;</strong> located in the same directory as this document.</p><img loading="lazy" height="268" width="757" class="common_img" src="'+Bn+'"><p>③ Select the <strong>&quot;ESP32S3 Dev Module&quot;</strong> as the target board.</p><img loading="lazy" height="497" width="693" class="common_img" src="'+Pn+'"><p>④ In the <strong>&quot;Tools&quot;</strong> menu, configure the ESP32-S3 development board settings as shown in the image below. (This configuration is only required for the first use. It does not need to be repeated for subsequent uses.)</p><img loading="lazy" height="367" width="476" class="common_img" src="'+xn+'"><p>⑤ Click <img loading="lazy" height="36" width="36" src="'+Zn+'"> to transfer the code to the ESP32-S3 and wait for the flashing process to complete.</p><img loading="lazy" height="41" width="559" class="common_img" src="'+Yn+'"><img loading="lazy" height="42" width="497" class="common_img" src="'+Mn+'"><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/Color%20Recognition%20Scratch%20Program.zip">Color Recognition Scratch Program.sb3</a></p><p>(1) Locate and open the program file <strong>&quot;04 Color Recognition Scratch Program.sb3&quot;</strong> from the same directory as this document.</p><img loading="lazy" height="22" width="372" class="common_img" src="'+Vn+'"><p>(2) Power on the device and connect it to your computer using a Type-C data cable.</p><p>(3) Click the <strong>&quot;Connect&quot;</strong> button and select the appropriate port.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+jn+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port number may vary depending on your computer&#39;s configuration. For example, in this section, the port used is &quot;<strong>COM4</strong>&quot;. However, avoid selecting &quot;<strong>COM1</strong>&quot;, as it is typically reserved for system communication.</p></section><p>(4) Once the device successfully pairs with the software, a confirmation message will appear, indicating that the connection was successful.</p><img loading="lazy" height="55" width="176" class="common_img" src="'+kn+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>① When the vision module detects red, the RGB light on the ultrasonic sensor turns red, and the dot matrix module displays the scrolling text &quot;<strong>Red</strong>&quot;.</p><p>② When the vision module detects blue, the RGB light on the ultrasonic sensor turns blue, and the dot matrix module displays the scrolling text &quot;<strong>Blue</strong>&quot;.</p><p>③ When the vision module detects green, the RGB light on the ultrasonic sensor turns green, and the dot matrix module displays the scrolling text &quot;<strong>Green</strong>&quot;.</p><p>④ When no color is detected, both the RGB light on the ultrasonic sensor and the dot matrix module turn off.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+q+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the dot matrix interface, ESP32-S3 vision module, ultrasonic module, and servos.</p><img loading="lazy" height="344" width="652" class="common_img" src="'+Qn+'"><p>(2) In the main program, repeatedly call the custom colorDetect function to obtain color recognition results. Use the color_num variable to identify the recognized color ID and display the corresponding color name in English on the dot matrix screen.</p><img loading="lazy" height="581" width="551" class="common_img" src="'+Ln+'"><p>(3) Within the colorDetect function, retrieve data for color IDs 1 through 3. When the vision module returns data for a color, check if the second element (representing the width of the detected color) is greater than 0. If so, the color is considered detected, and the color_num variable is updated with the corresponding color ID.</p><img loading="lazy" height="785" width="825" class="common_img" src="'+Dn+'"><ul><li><strong>FAQ</strong></li></ul><p><strong>Q:</strong> The colors detected by the camera are inaccurate or misidentified.</p><p><strong>A:</strong> To improve accuracy, reduce background noise and distractions. Using a solid-color or simpler background environment can help the camera detect colors more reliably.</p><h3 id="_5-4-4-color-tracking-project" tabindex="-1">5.4.4 Color Tracking Project <a class="header-anchor" href="#_5-4-4-color-tracking-project" aria-label="Permalink to &quot;5.4.4 Color Tracking Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>Tonybot, equipped with the ESP32-S3 vision module, tracks a red ball while the robot&#39;s head follows the ball&#39;s movement direction.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="470" width="1268" class="common_img" src="'+Nn+'"><ul><li><strong>Module Introduction</strong></li></ul><img loading="lazy" height="349" width="505" class="common_img" src="'+Xn+'" style="width:300px;"><p>The ESP32-S3 Vision Module is a compact camera module that can function as a standalone system. It captures images with its built-in camera, processes the data using the ESP32 microcontroller, and wirelessly transmits it via Wi-Fi. With support for various communication protocols and low-power features, this module is widely used in a range of IoT applications.</p><p>To get the detailed installation guide, please refer to &#39;<a href="#anchor_4_4_1"><strong>4.4.1 Introduction to ESP32S3 Vision Module</strong></a>&#39;.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/ESP32S3%20Color%20Recognition%20Example.zip">ESP32S3 Color Recognition Example</a></p><p>(1) ESP32-S3 Vision Module Program Download</p><p>① Connect the ESP32-S3 to your computer using a Type-C data cable.</p><p>② Open the program file <strong>&quot;03 ESP32S3 Color Recognition Example/ ESP32S3_ColorDetection/ ESP32S3_ColorDetection.ino&quot;</strong> located in the same directory as this document.</p><img loading="lazy" height="268" width="757" class="common_img" src="'+Hn+'"><p>③ Select the <strong>&quot;ESP32S3 Dev Module&quot;</strong> as the target board.</p><img loading="lazy" height="497" width="693" class="common_img" src="'+Wn+'"><p>④ In the <strong>&quot;Tools&quot;</strong> menu, configure the ESP32-S3 development board settings as shown in the image below. (This configuration is only required for the first use. It does not need to be repeated for subsequent uses.)</p><img loading="lazy" height="367" width="476" class="common_img" src="'+Kn+'"><p>⑤ Click <img loading="lazy" height="36" width="36" src="'+Fn+'"> to transfer the code to the ESP32-S3 and wait for the flashing process to complete.</p><img loading="lazy" height="41" width="559" class="common_img" src="'+Jn+'"><img loading="lazy" height="42" width="497" class="common_img" src="'+Gn+'"><p>⑥ After the flashing is complete, disconnect the Type-C data cable.</p><p>(2) Program Download</p><p><a href="../_static/source_code/04/Color%20Tracking%20Scratch%20Example.zip">Color Tracking Scratch Example.sb3</a></p><p>① Locate and open the program file <strong>&quot;03 Color Tracking Scratch Program.sb3&quot;</strong> from the same directory as this document.</p><img loading="lazy" height="25" width="405" class="common_img" src="'+_n+'"><p>② Power on the device and connect it to your computer using a Type-C data cable.</p><p>③ Click the <strong>&quot;Connect&quot;</strong> button and select the appropriate port.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+$n+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port number may vary depending on your computer&#39;s configuration. For example, in this section, the port used is &quot;<strong>COM4</strong>&quot;. However, avoid selecting &quot;<strong>COM1</strong>&quot;, as it is typically reserved for system communication.</p></section><p>④ Once the device successfully pairs with the software, a confirmation message will appear, indicating that the connection was successful.</p><img loading="lazy" height="55" width="176" class="common_img" src="'+ti+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>When we move the red ball in front of the ESP32-S3 vision module camera, the robot&#39;s head will follow the ball&#39;s movement.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+S+'"><ul><li><strong>Program Analysis</strong></li></ul><p><a href="../_static/source_code/04/Color%20Tracking%20Scratch%20Example.zip">Color Tracking Scratch Example.sb3</a></p><p>(1) Initialize the ESP32-S3 vision module, disable the RGB lights on the ultrasonic module (to avoid misdetection), and set the head servo to 90° (facing forward). Then, execute the standing motion sequence to make the robot stand.</p><img loading="lazy" height="291" width="640" class="common_img" src="'+ei+'"><p>(2) In the main program, retrieve the data for color ID 1 and set <em>x</em> as the x-coordinate of the color region&#39;s center. If <em>x</em> &gt; 150, this indicates that the color block is positioned toward the right of the vision module&#39;s field of view. In this case, adjust the servo to rotate right, ensuring the color block remains centered in the camera&#39;s view.</p><img loading="lazy" height="422" width="922" class="common_img" src="'+oi+'"><p>(3) If <em>x</em> &lt; 90, this means the color block is positioned toward the left. Adjust the servo to rotate left, again ensuring the block stays centered. Finally, if the angle exceeds 180, set it to 180 to prevent the servo from rotating beyond its limit.</p><img loading="lazy" height="408" width="797" class="common_img" src="'+si+'"><ul><li><strong>FAQ</strong></li></ul><p>Q: The colors detected by the camera are inaccurate or misidentified.</p><p>A: To improve accuracy, reduce background noise and distractions. Using a solid-color or simpler background environment can help the camera detect colors more reliably.</p><h3 id="_5-4-5-face-detection-project" tabindex="-1">5.4.5 Face Detection Project <a class="header-anchor" href="#_5-4-5-face-detection-project" aria-label="Permalink to &quot;5.4.5 Face Detection Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>This section demonstrates how the ESP32-S3 vision module detects faces. When a face is recognized, the robot performs a waving gesture to greet the person.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="470" width="1268" class="common_img" src="'+ni+'"><ul><li><strong>Module Introduction</strong></li></ul><img loading="lazy" height="349" width="505" class="common_img" src="'+ii+'" style="width:300px;"><p>The ESP32-S3 Vision Module is a compact camera module that can function as a standalone system. It captures images with its built-in camera, processes the data using the ESP32 microcontroller, and wirelessly transmits it via Wi-Fi. With support for various communication protocols and low-power features, this module is widely used in a range of IoT applications.</p><p>To get the detailed installation guide, please refer to &#39;<a href="#anchor_4_4_1"><strong>4.4.1 Overview and Installation of ESP32S3 Vision Module</strong></a>&#39;.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/ESP32S3%20Face%20Detection%20Example.zip">ESP32S3 Face Detection Example</a></p><p>(1) ESP32-S3 Vision Module Program Download</p><p>① Connect the ESP32-S3 to your computer using a Type-C data cable.</p><p>② Open the program file <strong>&quot;ESP32S3 Face Detection Example/ ESP32S3_FaceDetection/ ESP32S3_FaceDetection.ino&quot;</strong> located in the same directory as this document.</p><img loading="lazy" height="294" width="776" class="common_img" src="'+ai+'"><p>③ Select the <strong>&quot;ESP32S3 Dev Module&quot;</strong> as the target board.</p><img loading="lazy" height="497" width="693" class="common_img" src="'+ri+'"><p>④ In the &quot;Tools&quot; menu, configure the ESP32-S3 development board settings as shown in the image below. (<strong>This configuration is only required for the first use. It does not need to be repeated for subsequent uses.</strong>)</p><img loading="lazy" height="367" width="476" class="common_img" src="'+li+'"><p>⑤ Click <img loading="lazy" height="36" width="36" src="'+ci+'"> to transfer the code to the ESP32-S3 and wait for the flashing process to complete.</p><img loading="lazy" height="41" width="559" class="common_img" src="'+gi+'"><img loading="lazy" height="42" width="497" class="common_img" src="'+di+'"><p>⑥ After the flashing is complete, disconnect the Type-C data cable.</p><p>(2) Program Download</p><p><a href="../_static/source_code/04/Face%20Detection%20Scratch%20Example.zip">Face Detection Scratch Example.sb3</a></p><p>① Locate and open the program file <strong>&quot;03 Face Detection Scratch Program.sb3&quot;</strong> from the same directory as this document.</p><img loading="lazy" height="24" width="406" class="common_img" src="'+hi+'"><p>② Power on the device and connect it to your computer using a Type-C data cable.</p><p>③ Click the <strong>&quot;Connect&quot;</strong> button and select the appropriate port.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+mi+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port number may vary depending on your computer&#39;s configuration. For example, in this section, the port used is &quot;<strong>COM4</strong>&quot;. However, avoid selecting &quot;<strong>COM1</strong>&quot;. as it is typically reserved for system communication.</p></section><p>④ Once the device successfully pairs with the software, a confirmation message will appear, indicating that the connection was successful.</p><img loading="lazy" height="55" width="176" class="common_img" src="'+pi+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>When a face is detected, the robot will greet the person by performing a waving gesture.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+O+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the ESP32-S3 vision module, turn off the ultrasonic RGB lights (to prevent false detections), and set the robot to a standing position.</p><img loading="lazy" height="299" width="639" class="common_img" src="'+Ai+'"><p>(2) In the main program, retrieve the face detection data from the vision module. When a face is detected, execute action group 9 (the waving gesture).</p><img loading="lazy" height="360" width="729" class="common_img" src="'+ui+'"><h3 id="_5-4-6-vision-line-following-project" tabindex="-1">5.4.6 Vision Line Following Project <a class="header-anchor" href="#_5-4-6-vision-line-following-project" aria-label="Permalink to &quot;5.4.6 Vision Line Following Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>Tonybot, equipped with the ESP32-S3 vision module, detects red lines and follows their path. The robot moves accordingly, adjusting its position to stay aligned with the detected lines in its field of view.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="374" width="1230" class="common_img" src="'+bi+'"><ul><li><strong>Module Introduction</strong></li></ul><img loading="lazy" height="349" width="505" class="common_img" src="'+wi+'" style="width:300px;"><p>The ESP32-S3 Vision Module is a compact camera module that can function as a standalone system. It captures images with its built-in camera, processes the data using the ESP32 microcontroller, and wirelessly transmits it via Wi-Fi. With support for various communication protocols and low-power features, this module is widely used in a range of IoT applications.</p><p>To get the detailed installation guide, please refer to &#39;<a href="#anchor_4_4_1"><strong>4.4.1 Introduction to ESP32S3 Vision Module</strong></a>&#39;.</p><ul><li><strong>Program Download</strong></li></ul><p><a href="../_static/source_code/04/ESP32S3%20Color%20Recognition%20Example.zip">ESP32S3 Color Recognition Example</a></p><p>(1) ESP32-S3 Vision Module Program Download</p><p>① Connect the ESP32-S3 to your computer using a Type-C data cable.</p><p>② Open the program file <strong>&quot;02 ESP32S3 Color Recognition Example/ ESP32S3_ColorDetection/ ESP32S3_ColorDetection.ino&quot;</strong> located in the same directory as this document.</p><img loading="lazy" height="286" width="812" class="common_img" src="'+fi+'"><p>③ Select the <strong>&quot;ESP32S3 Dev Module&quot;</strong> as the target board.</p><img loading="lazy" height="497" width="693" class="common_img" src="'+yi+'"><p>④ In the <strong>&quot;Tools&quot;</strong> menu, configure the ESP32-S3 development board settings as shown in the image below. (<strong>This configuration is only required for the first use. It does not need to be repeated for subsequent uses.</strong>)</p><img loading="lazy" height="367" width="476" class="common_img" src="'+vi+'"><p>⑤ Click <img loading="lazy" height="36" width="36" src="'+Ti+'"> to transfer the code to the ESP32-S3 and wait for the flashing process to complete.</p><img loading="lazy" height="41" width="559" class="common_img" src="'+Ci+'"><img loading="lazy" height="42" width="497" class="common_img" src="'+Ei+'"><p>⑥ After the flashing is complete, disconnect the Type-C data cable.</p><p>(2) Program Download</p><p><a href="../_static/source_code/04/Vision%20Line%20Following%20Scratch%20Example.zip">Vision Line Following Scratch Example.sb3</a></p><p>① Locate and open the program file <strong>&quot;03 Vision Line Following Scratch Program.sb3&quot;</strong> from the same directory as this document.</p><img loading="lazy" height="24" width="409" class="common_img" src="'+zi+'"><p>② Power on the device and connect it to your computer using a Type-C data cable.</p><p>③ Click the <strong>&quot;Connect&quot;</strong> button and select the appropriate port.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+Ui+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port number may vary depending on your computer&#39;s configuration. For example, in this section, the port used is &quot;<strong>COM4</strong>&quot;. However, avoid selecting &quot;<strong>COM1</strong>&quot;, as it is typically reserved for system communication.</p></section><p>④ Once the device successfully pairs with the software, a confirmation message will appear, indicating that the connection was successful.</p><img loading="lazy" height="55" width="176" class="common_img" src="'+Ri+'"><ul><li><strong>Achieved Effect</strong></li></ul><p>When a face is detected, the robot will greet the person by performing a waving gesture.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+I+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the ESP32-S3 vision module, disable the ultrasonic RGB lights (to prevent false detection), and execute the standing action to make the robot upright.</p><img loading="lazy" height="284" width="620" class="common_img" src="'+qi+'"><p>(2) First, retrieve the data for color ID 1, and set the variable <strong>&quot;x&quot;</strong> to the x-coordinate of the detected color&#39;s center. If no action group is currently running, and if the x-coordinate is between 110 and 190, it indicates that the robot is on the line. In this case, execute action group 63 to make the robot move forward.</p><img loading="lazy" height="399" width="945" class="common_img" src="'+Si+'"><p>(3) If the x-coordinate is between 0 and 110, it means the line is to the robot&#39;s left. In this case, run action group 65 twice to make the robot turn left, and set the variable &quot;<strong>step</strong>&quot; to 1. The &quot;<strong>step</strong>&quot; variable controls the robot&#39;s movements: when set to 0, the robot moves forward; when set to 1, it turns left; when set to 2, it turns right.</p><img loading="lazy" height="176" width="858" class="common_img" src="'+Oi+'"><p>(4) If the line is detected to be on the robot&#39;s right (x &gt; 190), execute action group 66 twice to make the robot turn right, and set &quot;<strong>step</strong>&quot; to 2.</p><img loading="lazy" height="153" width="789" class="common_img" src="'+Ii+'"><p>(5) When step = 1, if the line is still on the left, continue running action group 65 once to make the robot turn left. If the line is no longer on the left, execute action group 63 once to move the robot forward.</p><img loading="lazy" height="315" width="846" class="common_img" src="'+Bi+'"><p>(6) When step = 2, if the line is still on the right, continue running action group 66 once to make the robot turn right. If the line is no longer on the right, execute action group 63 once to move the robot forward.</p><img loading="lazy" height="474" width="891" class="common_img" src="'+Pi+'"><ul><li><strong>FAQ</strong></li></ul><p>Q: The colors detected by the camera are inaccurate or misidentified.</p><p>A: To improve accuracy, reduce background noise and distractions. Using a solid-color or simpler background environment can help the camera detect colors more reliably.</p><h2 id="_5-5-iot-internet-of-things-course" tabindex="-1">5.5 IOT (Internet of Things) Course <a class="header-anchor" href="#_5-5-iot-internet-of-things-course" aria-label="Permalink to &quot;5.5 IOT (Internet of Things) Course&quot;">​</a></h2><p><a href="../_static/source_code/04/Tonybot%20IOT%20Example.zip"> Tonybot IOT Example.sb3</a></p><p id="anchor_4_5_1"></p><h3 id="_5-5-1-module-installation-wiring" tabindex="-1">5.5.1 Module Installation &amp; Wiring <a class="header-anchor" href="#_5-5-1-module-installation-wiring" aria-label="Permalink to &quot;5.5.1 Module Installation &amp; Wiring&quot;">​</a></h3><img loading="lazy" height="600" width="1200" class="common_img" src="'+B+'"><img loading="lazy" height="600" width="1200" class="common_img" src="'+P+'"><p id="anchor_4_5_2"></p><h3 id="_5-5-2-program-download" tabindex="-1">5.5.2 Program Download <a class="header-anchor" href="#_5-5-2-program-download" aria-label="Permalink to &quot;5.5.2 Program Download&quot;">​</a></h3><ul><li><strong>Vision Module Program Download</strong></li></ul><p>This section provides a step-by-step guide for downloading the ESP32-S3 vision module program, using the face detection program as an example. The process for downloading the color recognition program is identical to that of the face detection program.</p><p>(1) Program Download</p><p>① Connect the ESP32-S3 to your computer using a Type-C data cable.</p><p>② Open the program file &quot;<strong>02 Face Detection Porgram/FaceDetection/FaceDetection.ino</strong>&quot; located in the same directory as this document.</p><img loading="lazy" height="281" width="672" class="common_img" src="'+x+'"><p>③ Select the <strong>&quot;ESP32S3 Dev Module&quot;</strong> as the target board.</p><img loading="lazy" height="497" width="693" class="common_img" src="'+Z+'"><p>④ In the <strong>&quot;Tools&quot;</strong> menu, configure the ESP32-S3 development board settings as shown in the image below. (<strong>This configuration is only required for the first use. It does not need to be repeated for subsequent uses.</strong>)</p><img loading="lazy" height="367" width="476" class="common_img" src="'+Y+'"><p>⑤ Click <img loading="lazy" height="36" width="36" src="'+M+'"> to transfer the code to the ESP32-S3 and wait for the flashing process to complete.</p><img loading="lazy" height="41" width="559" class="common_img" src="'+V+'"><img loading="lazy" height="42" width="497" class="common_img" src="'+j+'"><p>⑥ After the flashing is complete, disconnect the Type-C data cable.</p><ul><li><strong>Tonybot IOT Program Download</strong></li></ul><p>(1) Preparation and Precautions</p><p>Before downloading the program, ensure that Tonybot is powered on and connected via a Type-C data cable. Otherwise, there may be an issue where the port cannot be detected.</p><p>(2) Program Download</p><p><a href="../_static/source_code/04/Tonybot%20IOT%20Example.zip"> Tonybot IOT Example.sb3</a></p><p>① Connect the ESP32-S3 to the computer using a Type-C data cable.</p><p>② Open the &quot;02 Tonybot IOT Example.sb3&quot; program file, which is located in the same directory as this document.</p><img loading="lazy" height="26" width="396" class="common_img" src="'+xi+'"><p>③ Power on the device and connect it to the computer via the Type-C data cable.</p><p>④ Click the &quot;Connect&quot; button and select the correct port.</p><img loading="lazy" height="362" width="974" class="common_img" src="'+Zi+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port number may vary depending on the computer. For example, the port number in this section is &quot;<strong>COM4</strong>&quot;. Avoid using &quot;<strong>COM1</strong>&quot;, as it is typically reserved for system communication.</p></section><p>⑤ Once the device is successfully paired with the software, a connection success message will appear.</p><img loading="lazy" height="55" width="176" class="common_img" src="'+Yi+'"><p>(3) Program Operation Results</p><p>After launching the mobile app, you can control Tonybot to perform functions such as face detection alerts, unknown object alerts, and collision alerts for unidentified items. For detailed information on how the program works, please refer to section &quot;<strong><a href="https://docs.hiwonder.com/projects/Tonybot/en/latest/docs/5.python_programming_projects.html#app-usage-instruction" target="_blank" rel="noreferrer">5.5.3 App Installation</a></strong>&quot;.</p><h3 id="_5-5-3-app-usage-instruction" tabindex="-1">5.5.3 App Usage Instruction <a class="header-anchor" href="#_5-5-3-app-usage-instruction" aria-label="Permalink to &quot;5.5.3 App Usage Instruction&quot;">​</a></h3><ul><li><strong>App Installation</strong></li></ul><p>For iOS users: Simply search for &quot;<a href="https://apps.apple.com/us/app/iot-control-hiwonder/id6738712087" target="_blank" rel="noreferrer"><strong>IoT Control</strong></a>&quot; in the App Store and download it.</p><p>For Android users: You can find the &quot;<a href="https://play.google.com/store/apps/details?id=com.hiwonder.mechdogiot" target="_blank" rel="noreferrer"><strong>IoT Control</strong></a>&quot;, or refer to the appendix to download and install it on your phone.</p><ul><li><strong>App Connection</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Before using the app, make sure that Wi-Fi and location services are enabled in your phone&#39;s settings. This section demonstrates using the Android version of the app, but the steps are the same for the iOS version.</p></section><p>(1) Power on the Tonybot, then open the <strong>&quot;IoT Control&quot;</strong> app on your phone.</p><img loading="lazy" height="225" width="207" class="common_img" src="'+k+'" style="width:100px;"><p>(2) Tap <img loading="lazy" height="29" width="33" src="'+Q+'" style="width:70px;"> in the top-right corner, select <strong>&quot;IOT_Tonybot&quot;</strong> from the Wi-Fi list, and enter the password <strong>&quot;12345678&quot;</strong> to connect.</p><img loading="lazy" height="426" width="606" class="common_img" src="'+L+'" style="width:300px;"><p>(3) Once connected, the Wi-Fi icon in the top-right corner will become solid.</p><img loading="lazy" height="1147" width="529" class="common_img" src="'+D+'" style="width:300px;"><ul><li><strong>Control Overview</strong></li></ul><p>The app provides 8 different modes: Face Detection Alert, Unknown Object Alert, Unknown Impact Alert, Remote Warning, Color Detection, Distance Detection, RGB Light Control, and Robot Control.</p><p>A detailed description of each function is provided in the table below:</p><table class="docutils-nobg" border="1"><colgroup><col><col></colgroup><tbody><tr><td><strong>Icon</strong></td><td><strong>Function</strong></td></tr><tr><td><img loading="lazy" height="227" width="218" src="'+N+'"></td><td>When the Tonybot vision module detects a face, the phone will vibrate.<br> (<strong>Note: This feature requires the face detection program to be pre-installed on the vision module.</strong>)</td></tr><tr><td><img loading="lazy" height="219" width="235" src="'+X+'"></td><td>When the Tonybot ultrasonic module detects an object, the buzzer will sound.</td></tr><tr><td><img loading="lazy" height="226" width="239" src="'+H+'"></td><td>When an unknown object causes Tonybot to fall, the buzzer will sound.</td></tr><tr><td><img loading="lazy" height="232" width="243" src="'+W+'"></td><td>Once activated, the buzzer will continue to sound until Tonybot is upright again.</td></tr><tr><td><img loading="lazy" height="196" width="190" src="'+K+'"></td><td>When the Tonybot vision module detects a specific color, the corresponding color will be displayed in the circle below.<br> (Note: This feature requires the color detection program to be pre-installed on the vision module.)</td></tr><tr><td><img loading="lazy" height="145" width="210" src="'+F+'"></td><td>With the Remote Distance Measurement feature enabled, the detected distance will be shown below.</td></tr><tr><td><img loading="lazy" height="121" width="207" src="'+J+'"></td><td>Controls the color of the RGB light on the Tonybot ultrasonic module.</td></tr><tr><td><img loading="lazy" height="148" width="129" src="'+G+'"></td><td>Controls Tonybot to execute various action groups.</td></tr></tbody></table><h3 id="_5-5-4-face-detection-alert-project" tabindex="-1">5.5.4 Face Detection Alert Project <a class="header-anchor" href="#_5-5-4-face-detection-alert-project" aria-label="Permalink to &quot;5.5.4 Face Detection Alert Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>In this section, Tonybot utilizes the ESP32-S3 vision module to detect faces and triggers a vibration alert on the phone upon face detection.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+Mi+'"><ul><li><strong>Module Introduction</strong></li></ul><p>(1) ESP32-S3 Vision Module</p><img loading="lazy" height="349" width="505" class="common_img" src="'+Vi+'" style="width:300px;"><p>The ESP32-S3 Vision Module is a compact camera module that can function as a standalone system. It captures images with its built-in camera, processes the data using the ESP32 microcontroller, and wirelessly transmits it via Wi-Fi. With support for various communication protocols and low-power features, this module is widely used in a range of IoT applications.</p><p>To get the detailed installation guide, please refer to <a href="#anchor_4_5_1">4.5.1 WiFi Module Installation &amp; Wiring</a>.</p><ul><li><strong>Program Download</strong></li></ul><p>For details on downloading the vision module and Tonybot program, please refer to <a href="#anchor_4_5_2">4.5.2 Program Download</a>.</p><ul><li><strong>Achieved Effect</strong></li></ul><p>When Tonybot detects a face, the phone will vibrate as an alert.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+_+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the Wi-Fi module interface and set the Wi-Fi module&#39;s name. Then, initialize the ESP32-S3 vision module, set the head servo angle to 90°, and execute the standing action sequence. Once initialization is complete, the buzzer will emit a sound as a reminder.</p><img loading="lazy" height="396" width="747" class="common_img" src="'+ji+'"><p>(2) Retrieve the functionality of the ESP32-S3 vision module. First, read the color recognition results. If the x-coordinate of the detected color region is not 0 and the x-coordinate is equal to its width, set esp32s3_type to 1 for face detection mode. If these conditions are not met, set esp32s3_type to 2 for color recognition mode.</p><img loading="lazy" height="495" width="910" class="common_img" src="'+ki+'"><p>(3) In the main program, if the vision module is set to face detection mode, check the onoff_face flag to determine if the face detection alert function is enabled. If enabled, obtain the face detection data from the vision module. When a face is detected, set warn_face to 1.</p><img loading="lazy" height="384" width="866" class="common_img" src="'+Qi+'"><p>(4) In another section of the main program, send the face detection alert, unknown object collision warning, and unknown object detection alert to the mobile app.</p><img loading="lazy" height="157" width="1018" class="common_img" src="'+Li+'"><h3 id="_5-5-5-unknown-impact-alert" tabindex="-1">5.5.5 Unknown Impact Alert <a class="header-anchor" href="#_5-5-5-unknown-impact-alert" aria-label="Permalink to &quot;5.5.5 Unknown Impact Alert&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>In this section, Tonybot will trigger a vibration alert on the phone when an object is detected by the IMU sensor.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+Di+'"><ul><li><strong>IMU Sensor</strong></li></ul><img loading="lazy" height="146" width="185" class="common_img" src="'+Ni+'"><p>Tonybot is equipped with an on-board IMU sensor, widely used in applications such as handheld gaming devices, 3D controllers, and portable navigation systems. This sensor integrates a 3-axis MEMS gyroscope, a 3-axis MEMS accelerometer, and a Digital Motion Processor (DMP) for advanced motion detection and processing.</p><ul><li><strong>S3 Vision Module Program Download</strong></li></ul><p>For details on downloading the vision module and Tonybot program, please refer to <a href="#anchor_4_5_2">4.5.2 Program Download</a>.</p><ul><li><strong>Achieved Effect</strong></li></ul><p>When Tonybot is knocked over by an unknown object, the phone will vibrate.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+$+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the Wi-Fi module interface and configure the Wi-Fi module&#39;s name. Then, initialize the ESP32-S3 vision module, set the head servo angle to 90°, and execute the standing action group. After the initialization is complete, the buzzer will sound to signal the completion.</p><img loading="lazy" height="396" width="747" class="common_img" src="'+Xi+'"><p>(2) Retrieve the ESP32-S3 vision module&#39;s functionality. First, read the color recognition result. If the x-coordinate of the detected color region is not 0 and the x-coordinate matches the width of the detected color region, set esp32s3_type to 1 (face recognition mode). If not, set esp32s3_type to 2 (color recognition mode).</p><img loading="lazy" height="495" width="910" class="common_img" src="'+Hi+'"><p>(3) When the unknown object collision detection feature is enabled (onoff_hit = 1), retrieve the IMU&#39;s roll angle data. If the roll angle is less than 70° or greater than 110°, set the warn_hit flag to 1.</p><img loading="lazy" height="293" width="670" class="common_img" src="'+Wi+'"><p>(4) In another main program, send the face detection warning, unknown object collision warning, and unknown object detection warning to the mobile app.</p><img loading="lazy" height="157" width="1018" src="'+Ki+'"><h3 id="_5-5-6-unknown-object-alert" tabindex="-1">5.5.6 Unknown Object Alert <a class="header-anchor" href="#_5-5-6-unknown-object-alert" aria-label="Permalink to &quot;5.5.6 Unknown Object Alert&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>This section shows how Tonybot uses the ultrasonic sensor to detect objects and sends a vibration alert to the mobile phone.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+Fi+'"><ul><li><strong>Module Introduction</strong></li></ul><img loading="lazy" height="323" width="497" class="common_img" src="'+Ji+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><ul><li><strong>S3 Vision Module Program Download</strong></li></ul><p>For details on downloading the vision module and Tonybot program, please refer to Section <a href="#anchor_4_5_2">4.5.2 Program Download</a>.</p><ul><li><strong>Achieved Effect</strong></li></ul><p>When Tonybot detects an object at a distance of less than 15 cm, the phone will vibrate.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+tt+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the Wi-Fi module interface and configure the Wi-Fi module name. Next, initialize the ESP32-S3 vision module, set the head servo angle to 90°, and execute the standing motion sequence. Once initialization is complete, the buzzer will sound as an indicator.</p><img loading="lazy" height="396" width="747" class="common_img" src="'+Gi+'"><p>(2) Retrieve the functionality of the ESP32-S3 vision module. Start by reading the results of color recognition. If the x-coordinate of the detected color area is not 0 and the x-coordinate equals the width of the detected area, set esp32s3_type to 1 for face recognition mode. Otherwise, set esp32s3_type to 2 for color recognition mode.</p><img loading="lazy" height="495" width="910" class="common_img" src="'+_i+'"><p>(3) Measure the obstacle distance using the ultrasonic sensor. When the undefined object warning is enabled (onoff_undef_obj = 1), evaluate the obstacle distance. If it is less than 20 cm, set the warn_undef_obj flag to 1.</p><img loading="lazy" height="210" width="722" class="common_img" src="'+$i+'"><p>(4) In a separate main program, send the face detection alert, undefined object collision warning, and undefined object alert to the mobile app.</p><img loading="lazy" height="157" width="1018" class="common_img" src="'+ta+'"><h3 id="_5-5-7-color-detection-project" tabindex="-1">5.5.7 Color Detection Project <a class="header-anchor" href="#_5-5-7-color-detection-project" aria-label="Permalink to &quot;5.5.7 Color Detection Project&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>This section allows Tonybot, equipped with the ESP32-S3 vision module, to detect red, green, and blue colors and display the corresponding colors on the mobile phone.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+ea+'"><ul><li><strong>Module Introduction</strong></li></ul><p>(1) ESP32-S3 Vision Module</p><img loading="lazy" height="349" width="505" class="common_img" src="'+oa+'" style="width:300px;"><p>The ESP32-S3 Vision Module is a compact camera module that can function as a standalone system. It captures images with its built-in camera, processes the data using the ESP32 microcontroller, and wirelessly transmits it via Wi-Fi. With support for various communication protocols and low-power features, this module is widely used in a range of IoT applications.</p><p>To get the detailed installation guide, please refer to <a href="#anchor_4_5_1">4.5.1 Module Installation &amp; Wiring</a></p><ul><li><strong>S3 Vision Module Program Download</strong></li></ul><p>For details on downloading the vision module and Tonybot program, please refer to <a href="#anchor_4_5_2">4.5.2 Program Download</a>.</p><ul><li><strong>Achieved Effect</strong></li></ul><p>When Tonybot detects red, green, or blue, it sends the data to the app, which then displays the recognized color.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+et+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the Wi-Fi module interface and configure the Wi-Fi module name. Then, initialize the ESP32-S3 vision module, set the head servo angle to 90°, and execute the standing motion sequence. Once initialization is complete, the buzzer will sound to indicate the process is finished.</p><img loading="lazy" height="396" width="747" class="common_img" src="'+sa+'"><p>(2) Retrieve the functionality of the ESP32-S3 vision module and read the color recognition results. If the x-coordinate of the detected color area is non-zero and the x-coordinate equals the width of the area, set esp32s3_type to 1 to enter face recognition mode. Otherwise, set esp32s3_type to 2 to enter color recognition mode.</p><img loading="lazy" height="495" width="910" class="common_img" src="'+na+'"><p>(3) Check if the vision module is set to color recognition mode. When the onoff_color_detec flag is 1, remote color detection is enabled. Then, call the colorDetect function to retrieve the recognition result, which will be stored in the color_detec_num variable.</p><img loading="lazy" height="224" width="637" class="common_img" src="'+ia+'"><p>(4) In the color recognition function, retrieve the vision module&#39;s recognition result. If the second element of the color data is greater than 0, it indicates the detected color area has a width greater than 0, meaning a color has been recognized. Set the color_num variable to the recognized color ID.</p><img loading="lazy" height="721" width="688" class="common_img" src="'+aa+'"><p>(5) Finally, send the recognized color ID to the app.</p><img loading="lazy" height="250" width="793" class="common_img" src="'+ra+'"><h3 id="_5-5-8-distance-detection" tabindex="-1">5.5.8 Distance Detection <a class="header-anchor" href="#_5-5-8-distance-detection" aria-label="Permalink to &quot;5.5.8 Distance Detection&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>This section enables Tonybot to measure the obstacle distance using an ultrasonic sensor and display the distance on the app.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+la+'"><ul><li><strong>Module Introduction</strong></li></ul><img loading="lazy" height="323" width="497" class="common_img" src="'+ca+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><ul><li><strong>S3 Vision Module Program Download</strong></li></ul><p>For details on downloading the vision module and Tonybot program, please refer to Section <a href="#anchor_4_5_2">4.5.2: Program Download</a>.</p><ul><li><strong>Achieved Effect</strong></li></ul><p>Tonybot will continuously monitor the distance to objects and display the measurement on the app.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+ot+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the Wi-Fi module interface and configure the Wi-Fi module name. Then, initialize the ESP32-S3 vision module, set the head servo angle to 90°, and execute the standing motion. Once initialization is complete, the buzzer will sound to indicate the process has finished.</p><img loading="lazy" height="396" width="747" class="common_img" src="'+ga+'"><p>(2) Retrieve the functionality of the ESP32-S3 vision module and read the color recognition results. If the x-coordinate of the detected color area is not 0 and the x-coordinate equals the width of the area, set esp32s3_type to 1 to enter face recognition mode. Otherwise, set esp32s3_type to 2 to enter color recognition mode.</p><img loading="lazy" height="495" width="910" class="common_img" src="'+da+'"><p>(3) Measure the obstacle distance using the ultrasonic sensor and store the result in the sensor_distance variable.</p><img loading="lazy" height="50" width="657" class="common_img" src="'+ha+'"><p>(4) In another main program, send the detected obstacle distance to the app.</p><img loading="lazy" height="187" width="771" class="common_img" src="'+ma+'"><h3 id="_5-5-9-rgb-light-control" tabindex="-1">5.5.9 RGB Light Control <a class="header-anchor" href="#_5-5-9-rgb-light-control" aria-label="Permalink to &quot;5.5.9 RGB Light Control&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>This section allows you to control the RGB light color of Tonybot&#39;s ultrasonic sensor through the app.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+pa+'"><ul><li><strong>Module Introduction</strong></li></ul><img loading="lazy" height="323" width="497" class="common_img" src="'+Aa+'" style="width:300px;"><p>This is a light-emitting ultrasonic distance sensor module that communicates via I2C. It reads the distance measured by the ultrasonic sensor using the I2C protocol.</p><p>When measuring distance, the module sends out 8 pulses of 40kHz square waves and checks for any returning signals. If a signal is detected, the module outputs a high-level signal, and the duration of this high signal corresponds to the time taken for the ultrasonic waves to travel to the target and back.</p><ul><li><strong>S3 Vision Module Program Download</strong></li></ul><p>For details on downloading the vision module and Tonybot program, please refer to Section <a href="#anchor_4_5_2">4.5.2 Program Download</a>.</p><ul><li><strong>Achieved Effect</strong></li></ul><p>Tonybot will adjust the RGB light color of the ultrasonic sensor according to the commands sent from the app.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+st+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the Wi-Fi module interface and configure the Wi-Fi module name. Then, initialize the ESP32-S3 vision module, set the head servo angle to 90°, and execute the standing motion. Once initialization is complete, the buzzer will sound to indicate the process has finished.</p><img loading="lazy" height="396" width="747" class="common_img" src="'+ua+'"><p>(2) Retrieve the functionality of the ESP32-S3 vision module and read the color recognition results. If the x-coordinate of the detected color area is non-zero and equals the width of the area, set esp32s3_type to 1 for face recognition mode. Otherwise, set esp32s3_type to 2 for color recognition mode.</p><img loading="lazy" height="495" width="910" class="common_img" src="'+ba+'"><p>(3) Use the Wi-Fi module to retrieve the data sent from the mobile app and store the parsed data in the cmd string.</p><img loading="lazy" height="400" width="566" class="common_img" src="'+wa+'"><p>(4) Using the first element of cmd, identify the command sent from the mobile app. When the command number is 4, it indicates a remote control command for the RGB light. We will then use the parsed data to control the ultrasonic RGB light and display the corresponding color.</p><img loading="lazy" height="83" width="973" class="common_img" src="'+fa+'"><h3 id="_5-5-10-remote-warning" tabindex="-1">5.5.10 Remote Warning <a class="header-anchor" href="#_5-5-10-remote-warning" aria-label="Permalink to &quot;5.5.10 Remote Warning&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>In this section, you will learn how to use the app to control Tonybot&#39;s buzzer and trigger sound.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+ya+'"><ul><li><strong>Module Introduction</strong></li></ul><img loading="lazy" height="196" width="197" class="common_img" src="'+va+'"><p>Tonybot is equipped with a 5V buzzer. By adjusting the frequency of the PWM signal output, the buzzer can produce sounds of different pitches.</p><ul><li><strong>S3 Vision Module Program Download</strong></li></ul><p>For details on downloading the vision module and Tonybot program, please refer to Section <a href="#anchor_4_5_2">4.5.2 Program Download</a>.</p><ul><li><strong>Achieved Effect</strong></li></ul><p>After enabling the remote warning feature, Tonybot&#39;s buzzer will sound.</p><img loading="lazy" height="360" width="640" class="common_img" src="'+nt+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Initialize the Wi-Fi module interface and set the name for the Wi-Fi module. Then, initialize the ESP32S3 vision module, set the head servo angle to 90°, and run the standing motion group. After the initialization, the buzzer will sound to provide a notification.</p><img loading="lazy" height="396" width="747" class="common_img" src="'+Ta+'"><p>(2) Retrieve the functions of the ESP32S3 vision module. First, read the results of color recognition. When the x-coordinate of the detected color region is not 0 and the x-coordinate of the detected color region equals its width, set the esp32s3_type to 1, indicating facial recognition mode. Otherwise, set esp32s3_type to 2, indicating color recognition mode.</p><img loading="lazy" height="495" width="910" class="common_img" src="'+Ca+'"><p>(3) First, obtain the obstacle distance from the ultrasonic sensor and store it in the sensor_distance variable.</p><img loading="lazy" height="51" width="545" class="common_img" src="'+Ea+'"><p>(4) Then, retrieve the data sent from the mobile app via the Wi-Fi module, and store the parsed data in the cmd string.</p><img loading="lazy" height="440" width="978" class="common_img" src="'+za+'"><p>(5) When the first element of the parsed data is 5, set buzzer_flag to 0 to turn off the buzzer alarm. When the second element of the parsed data is greater than 0, indicating that the remote alert feature is enabled, set the buzzer_flag variable to 1.</p><img loading="lazy" height="215" width="922" class="common_img" src="'+Ua+'"><p>(6) Finally, in another main program, run the buzzer alarm function. When the buzzer_flag variable is set to 1, control the buzzer to sound the alarm.</p><img loading="lazy" height="296" width="638" class="common_img" src="'+Ra+'"><h3 id="_5-5-11-robot-control" tabindex="-1">5.5.11 Robot Control <a class="header-anchor" href="#_5-5-11-robot-control" aria-label="Permalink to &quot;5.5.11 Robot Control&quot;">​</a></h3><ul><li><strong>Project Introduction</strong></li></ul><p>In this section, you&#39;ll use the mobile app to control Tonybot and make it perform a series of actions.</p><ul><li><strong>Program Implementation Process</strong></li></ul><img loading="lazy" height="340" width="1268" class="common_img" src="'+qa+'"><ul><li><strong>S3 Vision Module Program Download</strong></li></ul><p>For details on downloading the vision module and Tonybot program, please refer to Section <a href="#anchor_4_5_2">4.5.2 Program Download</a>.</p><ul><li><strong>Achieved Effect</strong></li></ul><p>Tonybot includes 16 built-in action groups, and we can call these action groups to make Tonybot perform the corresponding actions. The specific action groups are shown in the table below:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Action Group Name</strong></th><th style="text-align:center;"><strong>Content</strong></th></tr></thead><tbody><tr><td style="text-align:center;">left_foot_kick</td><td style="text-align:center;">Left Foot Kick</td></tr><tr><td style="text-align:center;">right_foot_kick</td><td style="text-align:center;">Right Foot Kick</td></tr><tr><td style="text-align:center;">stand_four_legs</td><td style="text-align:center;">Four-Legged Stand</td></tr><tr><td style="text-align:center;">sit_dowm</td><td style="text-align:center;">Sit Down</td></tr><tr><td style="text-align:center;">go_prone</td><td style="text-align:center;">Lie Down</td></tr><tr><td style="text-align:center;">stand_two_legs</td><td style="text-align:center;">Two-Legged Stand</td></tr><tr><td style="text-align:center;">handshake</td><td style="text-align:center;">Handshake</td></tr><tr><td style="text-align:center;">scrape_a_bow</td><td style="text-align:center;">Bow</td></tr><tr><td style="text-align:center;">nodding_motion</td><td style="text-align:center;">Nod</td></tr><tr><td style="text-align:center;">boxing</td><td style="text-align:center;">Boxing</td></tr><tr><td style="text-align:center;">stretch_oneself</td><td style="text-align:center;">Stretch</td></tr><tr><td style="text-align:center;">pee</td><td style="text-align:center;">Urinate</td></tr><tr><td style="text-align:center;">press_up</td><td style="text-align:center;">Push-up</td></tr><tr><td style="text-align:center;">rotation_pitch</td><td style="text-align:center;">Rotate Pitch</td></tr><tr><td style="text-align:center;">rotation_roll</td><td style="text-align:center;">Rotate Roll</td></tr><tr><td style="text-align:center;">normal_attitude</td><td style="text-align:center;">Attention (Stand at Attention)</td></tr></tbody></table><img loading="lazy" height="360" width="640" class="common_img" src="'+it+'"><ul><li><strong>Program Analysis</strong></li></ul><p>(1) First, initialize the Wi-Fi module interface and set its name. Then, initialize the ESP32S3 vision module, adjust the head servo angle to 90°, and run the standing action group. Once the initialization is complete, the buzzer will sound as a reminder.</p><img loading="lazy" height="396" width="747" class="common_img" src="'+Sa+'"><p>(2) Access the functions of the ESP32S3 vision module and read the color recognition results. When the x-coordinate of the color region is not 0 and equals the width of the color region, set esp32s3_type to 1, indicating facial recognition mode. Otherwise, set esp32s3_type to 2, indicating color recognition mode.</p><img loading="lazy" height="495" width="910" class="common_img" src="'+Oa+'"><p>(3) Retrieve data from the mobile app via the Wi-Fi module and store the parsed data in the cmd string.</p><img loading="lazy" height="440" width="978" class="common_img" src="'+Ia+'"><p>(4) When the first element of the parsed data is 6, it indicates a remote control command. At this point, check if the robot is currently running an action group. If not, execute the designated action group. Then, determine if the action group requires a squat position. If it does, execute it directly. If not, first run action group 19 (Quick Attention), and then execute the target action group.</p><img loading="lazy" height="396" width="1012" class="common_img" src="'+Ba+'"><h2 id="_5-6-serial-communication-course" tabindex="-1">5.6 Serial Communication Course <a class="header-anchor" href="#_5-6-serial-communication-course" aria-label="Permalink to &quot;5.6 Serial Communication Course&quot;">​</a></h2><h3 id="_5-6-1-master-slave-communication-principles" tabindex="-1">5.6.1 Master-Slave Communication Principles <a class="header-anchor" href="#_5-6-1-master-slave-communication-principles" aria-label="Permalink to &quot;5.6.1 Master-Slave Communication Principles&quot;">​</a></h3><p>In this section, we&#39;ll explore how Tonybot communicates with various devices (like STM32, 51 microcontrollers, Arduino, Raspberry Pi, etc.) in a master-slave relationship. You&#39;ll learn how Tonybot functions as a slave device for data exchange, and how other devices act as masters to control Tonybot.</p><p>Throughout this chapter, Tonybot operates as a slave device, using the UART serial port to exchange information with other devices.</p><ul><li><strong>Master-Slave Relationship</strong></li></ul><p>In the master-slave control system, Tonybot functions as a slave, working alongside other devices (like microcontrollers) that act as the master to control the system.</p><p>(1) Tonybot&#39;s Functions as a Slave Device</p><p>① Receive and Parse Signals from the Master</p><p>Tonybot waits for incoming serial signals. Once data is received, it parses the information according to the communication protocol and calls the corresponding function based on the data.</p><p>② Execute Actions Triggered by the Received Data</p><p>After parsing the signal, Tonybot executes the required action, such as triggering a pre-set action group or reading data from the ultrasonic sensor.</p><p>③ Data Packaging and Feedback</p><p>When a read command is received, Tonybot calls the appropriate read function, retrieves the data, packages it according to the communication protocol, and sends it back to the master device.</p><p>(2) Other Devices as the Master</p><p>① Command Packaging and Sending</p><p>The master device packages control commands and relevant data into data packets according to the communication protocol and sends them to the device.</p><p>② Control Coordination</p><p>The master device is responsible for managing the system&#39;s operations, ensuring smooth communication between Tonybot and other devices, avoiding conflicts, and keeping the entire system stable.</p><p>③ Data Reception</p><p>When the master needs to read Tonybot&#39;s status, it sends the read command and then receives the status data from Tonybot. The master must ensure the data&#39;s integrity and accuracy, parse the data packets, and extract the useful information.</p><ul><li><strong>Hardware Connection</strong></li></ul><p>For example, connecting Tonybot to a PC:</p><p>Connect the TXD, RXD, and GND pins of the USB-to-serial adapter to the D6, D7, and GND pins on Tonybot using DuPont wires, and then connect the USB adapter to the computer. (Note: The 5V connection is optional, but the GND connection is required.)</p><img loading="lazy" height="632" width="1200" class="common_img" src="'+bt+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>The power supplies for the master device and Tonybot can be different, but they must share a common ground to ensure stable communication levels.</p></li><li><p>When wiring, ensure that the TX and RX pins of the UART serial port are crossed (TX to RX, RX to TX); otherwise, communication will not be possible.</p></li></ul></section><ul><li><strong>Data Transmission Format</strong></li></ul><p>The default data transmission format for the UART serial port on Tonybot is as follows:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Baud Rate</th><th style="text-align:center;">9600</th></tr></thead><tbody><tr><td style="text-align:center;">Data Bits</td><td style="text-align:center;">8</td></tr><tr><td style="text-align:center;">Parity Bit</td><td style="text-align:center;">None</td></tr><tr><td style="text-align:center;">Stop Bit</td><td style="text-align:center;">1</td></tr></tbody></table><ul><li><strong>Communication Protocol</strong></li></ul><p>The command format sent from the master to Tonybot is as follows: it begins with &quot;<strong>CMD</strong>&quot;, followed by command parameters separated by &quot;<strong>|</strong>&quot;. and ends with &quot;<strong>$</strong>&quot;.</p><h3 id="_5-6-2-pc-serial-port-control" tabindex="-1">5.6.2 PC Serial Port Control <a class="header-anchor" href="#_5-6-2-pc-serial-port-control" aria-label="Permalink to &quot;5.6.2 PC Serial Port Control&quot;">​</a></h3><p>This document demonstrates how to sequentially control Tonybot&#39;s action groups, head servo, read battery levels, capture ultrasonic data, and retrieve IMU data through the PC serial port.</p><ul><li><strong>Program Logic</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>To proceed with this section, make sure the Tonybot slave-side program is downloaded first. You can find the &quot;<strong>Tonybot Slave-side Program</strong>&quot; in the same directory as this document.</p></section><p>(1) After connecting Tonybot to TTL for serial communication, it can be connected to a PC for UART communication. This enables serial control of Tonybot. The default UART data transmission format is as follows:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Baud rate</th><th style="text-align:center;">9600</th></tr></thead><tbody><tr><td style="text-align:center;">Data bit</td><td style="text-align:center;">8</td></tr><tr><td style="text-align:center;">Parity bit</td><td style="text-align:center;">None</td></tr><tr><td style="text-align:center;">Stop bit</td><td style="text-align:center;">1</td></tr></tbody></table><ul><li><strong>Communication protocol</strong></li></ul><p>Next, we will explain the format of the protocol command packet. The format is as follows: it begins with &quot;<strong>CMD</strong>&quot;, parameters are separated by &quot;<strong>|</strong>&quot;. and ends with &quot;<strong>$</strong>&quot;.</p><ul><li><strong>Preparation</strong></li></ul><p>(1) Hardware Preparation</p><p>Connect the TXD, RXD, and GND pins of the USB-to-serial adapter to the IO27, IO19, and GND pins on Tonybot using DuPont wires. Then, plug the USB adapter into the computer. (Note: The 5V connection is optional, but the GND connection is mandatory.)</p><img loading="lazy" height="806" width="1268" class="common_img" src="'+at+'"><p>(2) Software Preparation</p><p>① First, navigate to the <strong>&quot;Serial Port Debugging Tool&quot;</strong> in the same folder as this section&#39;s content.</p><img loading="lazy" height="45" width="419" class="common_img" src="'+rt+'"><p>② Once you open the tool, make sure to set the baud rate to 9600, choose NONE for the parity bit, set data bits to 8, and stop bits to 1. Don&#39;t forget to check the &quot;<strong>Send as ASCII</strong>&quot; option. The configuration should look like the one shown below:</p><img loading="lazy" height="468" width="214" class="common_img" src="'+lt+'"><ul><li><strong>Function Implementation</strong></li></ul><p>Control Tonybot by sending protocol commands:</p><p>(1) <strong>Command Name:</strong> Action Group Call</p><p><strong>Function Code:</strong> 1</p><p><strong>Command Data:</strong> Action group number, ranging from 0 to 255, corresponding to action groups 0-255.</p><p><strong>Description:</strong> This command is used to instruct Tonybot to execute a specific action group.</p><p><strong>Example:</strong> Sending the command &quot;<strong>CMD|1|0|$</strong>&quot; will make Tonybot perform the &quot;<strong>Stand at Attention</strong>&quot; action group.</p><img loading="lazy" height="71" width="690" class="common_img" src="'+ct+'"><p>(2) <strong>Command Name:</strong> Head Servo Control</p><p><strong>Function Code:</strong> 2</p><p><strong>Command Data:</strong> Servo angle, ranging from 0 to 180, corresponding to angles from 0° to 180°.</p><p><strong>Description:</strong> This command controls the movement of Tonybot&#39;s head servo.</p><p><strong>Example:</strong> Sending the command &quot;<strong>CMD|2|90|$</strong>&quot; will rotate the head servo to a 90° position.</p><img loading="lazy" height="71" width="690" class="common_img" src="'+gt+'"><p>(3) <strong>Command Name:</strong> Battery Voltage</p><p><strong>Function Code:</strong> 3</p><p><strong>Command Data:</strong> This is a read operation, so no command data is needed.</p><p><strong>Description:</strong> This command retrieves Tonybot&#39;s battery voltage, in millivolts (mV).</p><p><strong>Example:</strong> Sending the command &quot;<strong>CMD|3|$</strong>&quot; will request the battery voltage.</p><img loading="lazy" height="71" width="690" class="common_img" src="'+dt+'"><p>After sending the data, Tonybot will return the requested information in the format:</p><p>&quot;<strong>CMD|Function Code|data|$</strong>&quot;, where &quot;<strong>data</strong>&quot; represents the retrieved value.</p><img loading="lazy" height="60" width="335" class="common_img" src="'+ht+'"><p>(4) <strong>Command Name:</strong> Ultrasonic Data</p><p><strong>Function Code:</strong> 4</p><p><strong>Command Data:</strong> This is a read operation, so no command data is required.</p><p><strong>Description:</strong> This command retrieves the distance measured by Tonybot&#39;s ultrasonic sensor.</p><p><strong>Example:</strong> Sending the command &quot;<strong>CMD|4|$</strong>&quot; will return the distance detected by the ultrasonic sensor, in millimeters (mm).</p><img loading="lazy" height="71" width="691" class="common_img" src="'+mt+'"><p>After sending the data, Tonybot will return the requested information in the format:</p><p>&quot;<strong>CMD|Function Code|data|$</strong>&quot;, where &quot;<strong>data</strong>&quot; represents the retrieved distance.</p><img loading="lazy" height="61" width="362" class="common_img" src="'+pt+'"><p>(5) <strong>Command Name:</strong> IMU Data</p><p><strong>Function Code:</strong> 5</p><p><strong>Command Data:</strong> This is a read operation, so no command data is needed.</p><p><strong>Description:</strong> This command retrieves Tonybot&#39;s tilt angles along the X and Y axes, measured in degrees.</p><p><strong>Example:</strong> Sending the command &quot;<strong>CMD|5|$</strong>&quot; will return the IMU data.</p><img loading="lazy" height="71" width="693" class="common_img" src="'+At+'"><p>After sending the data, Tonybot will return the requested information in the format:</p><p>&quot;<strong>CMD|Function Code|x|y|$</strong>&quot;, where &quot;<strong>x</strong>&quot; and &quot;<strong>y</strong>&quot; represent the tilt angles on the X and Y axes.</p><img loading="lazy" height="60" width="316" class="common_img" src="'+ut+'">',1179)])])}const Na=wt(Pa,[["render",xa]]);export{Da as __pageData,Na as default};
